internal/lower/arguments_length.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

func (l *lowering) builtinArguments(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindIdentifier || node.Text() != "arguments" {
		return false
	}
	symbol := l.checker.GetSymbolAtLocation(node)
	return symbol != nil && len(symbol.Declarations) == 0
}

func (l *lowering) isArgumentsLength(node *ast.Node) bool {
	if node.Kind != ast.KindPropertyAccessExpression {
		return false
	}
	access := node.AsPropertyAccessExpression()
	return access.Name().Text() == "length" && access.QuestionDotToken == nil && l.builtinArguments(access.Expression)
}

func (l *lowering) argumentsRefusal(node *ast.Node) error {
	for owner := node.Parent; owner != nil; owner = owner.Parent {
		if ast.IsFunctionLike(owner) {
			if owner.Kind == ast.KindArrowFunction {
				return &Refused{Where: l.program.Where(node), What: "arguments inside an arrow function", Fix: "read arguments.length in the enclosing non-arrow function and capture that number"}
			}
			break
		}
	}
	value := node
	for value.Parent != nil && value.Parent.Kind == ast.KindParenthesizedExpression {
		value = value.Parent
	}
	if value.Parent != nil && l.isArgumentsLength(value.Parent) {
		length := value.Parent
		for length.Parent != nil && length.Parent.Kind == ast.KindParenthesizedExpression {
			length = length.Parent
		}
		if !ast.IsAssignmentTarget(length) {
			return nil
		}
		return &Refused{Where: l.program.Where(node), What: "writing arguments.length", Fix: "keep the count read-only; write an explicit local number instead"}
	}
	return &Refused{Where: l.program.Where(node), What: "arguments other than a read of arguments.length", Fix: "name the parameters, or take a rest parameter; only arguments.length may be read"}
}

func (l *lowering) readArgumentsCount() ir.Expression {
	if l.function == nil {
		panic("lower: arguments.length outside a function")
	}
	l.function.ReadsArguments = true
	if l.function.ArgumentsCount == 0 {
		local := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: "argument_count", Type: ir.Number, Function: l.functionIndex})
		l.function.ArgumentsCount = local + 1
	}
	return ir.Read{Local: l.function.ArgumentsCount - 1, Of: ir.Number}
}

// callArguments keeps spreads at their evaluation point. Backends expand them once,
// before evaluating the next argument, so a later mutation cannot change the count.
func (l *lowering) callArguments(nodes []*ast.Node) ([]ir.Expression, []bool, error) {
	arguments := []ir.Expression{}
	spread := make([]bool, len(nodes))
	anySpread := false
	for index, node := range nodes {
		value := node
		if node.Kind == ast.KindSpreadElement {
			value = node.AsSpreadElement().Expression
			proven := l.concrete(l.checker.GetTypeAtLocation(value))
			if checker.IsTupleType(proven) && ast.SkipParentheses(value).Kind == ast.KindArrayLiteralExpression {
				elements := l.checker.GetTypeArguments(proven)
				element := ir.Number
				for position, provenElement := range elements {
					of, known := l.representation(provenElement)
					if !known || slotless(of) || position > 0 && of != element {
						return nil, nil, l.notYet(node, "a call spreading a tuple with differently represented elements")
					}
					element = of
				}
				values, nested, err := l.callArguments(ast.SkipParentheses(value).AsArrayLiteralExpression().Elements.Nodes)
				if err != nil {
					return nil, nil, err
				}
				arguments = append(arguments, ir.ArrayLiteral{Element: element, Elements: values, Spread: nested})
				spread[index], anySpread = true, true
				continue
			}
			if !l.checker.IsArrayType(proven) {
				return nil, nil, l.notYet(node, "a call spreading something other than an array")
			}
			elements := l.checker.GetTypeArguments(proven)
			if len(elements) != 1 {
				return nil, nil, l.notYet(node, "a call spreading an array without one element type")
			}
			element, known := l.representation(elements[0])
			if !known || slotless(element) {
				return nil, nil, l.notYet(node, "a call spreading elements that cannot be packed")
			}
			spread[index], anySpread = true, true
		}
		lowered, err := l.expression(value)
		if err != nil {
			return nil, nil, err
		}
		arguments = append(arguments, lowered)
	}
	if !anySpread {
		spread = nil
	}
	return arguments, spread, nil
}

// resolveCountTypes uses the same assignability relation and closed-world function
// records as the cycle finder. A parameter or mutable function value is bounded
// by every implementation that can be seen through its function type.
func (l *lowering) resolveCountTypes(modules []*ast.SourceFile) {
	types := map[int]*checker.Type{}
	for _, module := range modules {
		var visit ast.Visitor
		visit = func(node *ast.Node) bool {
			if node.Kind == ast.KindCallExpression {
				proven := l.concrete(l.checker.GetTypeAtLocation(node.AsCallExpression().Expression))
				types[int(proven.Id())] = proven
				for _, argument := range node.AsCallExpression().Arguments.Nodes {
					callback := l.concrete(l.checker.GetTypeAtLocation(argument))
					if len(l.checker.GetSignaturesOfType(callback, checker.SignatureKindCall)) > 0 {
						types[int(callback.Id())] = callback
					}
				}
			}
			return node.ForEachChild(visit)
		}
		module.AsNode().ForEachChild(visit)
	}
	for _, proven := range l.localTypes {
		if proven != nil {
			proven = l.concrete(proven)
			types[int(proven.Id())] = proven
		}
	}
	l.resolveStructuralMethodThunks(modules)
	l.result.FunctionTypeTargets = map[int][]int{}
	for id, proven := range types {
		l.result.FunctionTypeTargets[id] = []int{}
		for _, record := range l.closureRecords {
			if l.checker.IsTypeAssignableTo(record.proven, proven) {
				l.result.FunctionTypeTargets[id] = append(l.result.FunctionTypeTargets[id], record.function)
			}
		}
	}
	// Reader facts must remain separate from padding a virtual C signature.
	for changed := true; changed; {
		changed = false
		for index := range l.result.Functions {
			function := &l.result.Functions[index]
			if function.ForwardsArguments != 0 && !function.ReadsArguments && l.result.Functions[function.ForwardsArguments-1].ReadsArguments {
				function.ReadsArguments = true
				changed = true
			}
		}
	}
	l.result.PrepareArgumentSlots()
	// Every virtual implementation must have the same native signature, including
	// an implementation that does not itself observe the count.
	changed := true
	for changed {
		changed = false
		for index := range l.result.Functions {
			function := &l.result.Functions[index]
			if function.ForwardsArguments == 0 || function.ArgumentsCount != 0 || l.result.Functions[function.ForwardsArguments-1].ArgumentsCount == 0 {
				continue
			}
			local := len(l.result.Locals)
			l.result.Locals = append(l.result.Locals, ir.Local{Name: "argument_count", Type: ir.Number, Function: index})
			function.ArgumentsCount = local + 1
			changed = true
		}
		for signature, implementations := range l.result.MethodTargets {
			targets := append([]int{signature}, implementations...)
			reads := false
			for _, target := range targets {
				reads = reads || l.result.Functions[target].ArgumentsCount != 0
			}
			if !reads {
				continue
			}
			for _, target := range targets {
				if l.result.Functions[target].ArgumentsCount == 0 {
					local := len(l.result.Locals)
					l.result.Locals = append(l.result.Locals, ir.Local{Name: "argument_count", Type: ir.Number, Function: target})
					l.result.Functions[target].ArgumentsCount = local + 1
					changed = true
				}
			}
		}
	}
}

func (l *lowering) fitCallArguments(function int, arguments []ir.Expression, spread []bool) {
	// Fixed arguments are fitted by the native call boundary, after ownership
	// planning. Fitting them here creates extra owned Weak and Union values.
	declared := l.result.Functions[function]
	position := 0
	expanded := false
	for index := range arguments {
		if len(spread) > index && spread[index] {
			expanded = true
			continue
		}
		if declared.RestElement != 0 && (expanded || position >= len(declared.Parameters)-1) {
			arguments[index] = fit(arguments[index], declared.RestElement)
		}
		position++
	}
}

// Optional method admission must account for the receiver, not just an assignable
// function signature. An own closure facade does not make every class with a
// same-signature method reachable. This does not narrow the count candidate set.
func (l *lowering) resolveStructuralMethodThunks(modules []*ast.SourceFile) {
	l.result.StructuralMethodThunks = map[int]bool{}
	finder := cycleFinder{l: l}
	// A derived receiver can expose an inherited implementation through a wider
	// structural view. Include every instantiation using that implementation.
	actualReceivers := map[int][]*checker.Type{}
	for _, instance := range l.instances {
		for _, function := range instance.methods {
			for _, local := range instance.thisLocals {
				actualReceivers[function] = append(actualReceivers[function], l.localTypes[local])
				actualReceivers[function] = append(actualReceivers[function], l.localAlso[local]...)
			}
		}
	}
	for _, module := range modules {
		var visit ast.Visitor
		visit = func(node *ast.Node) bool {
			if node.Kind == ast.KindCallExpression {
				callee := ast.SkipParentheses(node.AsCallExpression().Expression)
				if callee.Kind == ast.KindElementAccessExpression {
					// Computed callees do not retain a receiver-name proof here.
					// Preserve every method thunk rather than guessing a target.
					for index, function := range l.result.Functions {
						if function.Receiver {
							l.result.StructuralMethodThunks[index] = true
						}
					}
				}
				if callee.Kind == ast.KindPropertyAccessExpression {
					access := callee.AsPropertyAccessExpression()
					receiver := l.concrete(l.checker.GetTypeAtLocation(access.Expression))
					method := l.checker.GetSymbolAtLocation(callee)
					nativeMethod := method != nil && len(method.Declarations) > 0 && method.Declarations[0].Kind == ast.KindMethodDeclaration && access.QuestionDotToken == nil
					if !nativeMethod {
						for index, function := range l.result.Functions {
							if !function.Receiver || function.MethodName != access.Name().Text() || len(function.Parameters) == 0 {
								continue
							}
							local := function.Parameters[0]
							actuals := append([]*checker.Type{l.localTypes[local]}, l.localAlso[local]...)
							actuals = append(actuals, actualReceivers[index]...)
							for _, actual := range actuals {
								if actual == nil || finder.template(receiver) || finder.template(actual) || l.checker.IsTypeAssignableTo(actual, receiver) {
									l.result.StructuralMethodThunks[index] = true
								}
							}
						}
					}
				}
			}
			return node.ForEachChild(visit)
		}
		module.AsNode().ForEachChild(visit)
	}
}

internal/lower/library_array_predicate.g:
package lower

import (
	_ "unsafe"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

func (l *lowering) isArrayPredicateCall(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindCallExpression {
		return false
	}
	call := node.AsCallExpression()
	callee := ast.SkipParentheses(call.Expression)
	return call.QuestionDotToken == nil && len(call.Arguments.Nodes) == 1 && callee.Kind == ast.KindPropertyAccessExpression && callee.AsPropertyAccessExpression().QuestionDotToken == nil && callee.Name().Text() == "isArray" && l.isLibraryGlobal(callee.AsPropertyAccessExpression().Expression, "Array") && l.libraryMember(callee)
}

func (l *lowering) arrayIsArray(node *ast.Node) (ir.Expression, bool, error) {
	if !l.isArrayPredicateCall(node) {
		return nil, false, nil
	}
	argument := node.AsCallExpression().Arguments.Nodes[0]
	if !l.arrayPredicateDomain(l.checker.GetTypeAtLocation(argument)) && !l.exactObject(argument, 0) {
		return nil, true, l.notYet(argument, "Array.isArray on a tuple or an erased object/any/unknown view")
	}
	value, err := l.expression(argument)
	if err != nil {
		return nil, true, err
	}
	return ir.ArrayIsArray{Value: fit(value, ir.Union)}, true, nil
}

// The library's any[] predicate describes the runtime test, not an element
// contract. Only array members already promised by the declared input survive.
func (l *lowering) arrayPredicateMembers(proven *checker.Type, array bool) *checker.Type {
	members := []*checker.Type{}
	var collect func(*checker.Type)
	collect = func(member *checker.Type) {
		member = l.concrete(member)
		if member.Flags()&checker.TypeFlagsUnion != 0 {
			for _, part := range member.Types() {
				collect(part)
			}
			return
		}
		if member.Flags()&checker.TypeFlagsUnknown != 0 {
			if array {
				members = append(members, predicateReadonlyArray(l.checker, member, true))
			} else {
				members = append(members, member)
			}
			return
		}
		if member.Flags()&(checker.TypeFlagsAny|checker.TypeFlagsTypeParameter) != 0 {
			return
		}
		if l.checker.IsArrayType(member) == array {
			members = append(members, member)
		}
	}
	collect(proven)
	return l.checker.GetUnionType(members)
}

// Tuples currently have an object representation. Erased object views can hide
// one too, so the native array brand cannot decide their JavaScript arrayness.
func (l *lowering) arrayPredicateDomain(proven *checker.Type) bool {
	proven = l.concrete(proven)
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range proven.Types() {
			if !l.arrayPredicateDomain(member) {
				return false
			}
		}
		return true
	}
	if proven.Flags()&checker.TypeFlagsUnknown != 0 {
		return true
	}
	if proven.Flags()&(checker.TypeFlagsAny|checker.TypeFlagsTypeParameter|checker.TypeFlagsIntersection) != 0 || checker.IsTupleType(proven) {
		return false
	}
	if l.checker.IsArrayType(proven) {
		return true
	}
	return proven.Flags()&checker.TypeFlagsObject == 0 || isClassInstance(proven) || l.isLibraryType(proven, "Uint8Array", "Int32Array", "Float64Array")
}

// TypeScript's built-in signature is value is any[]. Recover the declared
// array member at a direct, dominating positive test instead of adopting any.
func (l *lowering) arrayPredicateType(node *ast.Node) *checker.Type {
	node = ast.SkipParentheses(node)
	actual := l.checker.GetTypeAtLocation(node)
	if node.Kind != ast.KindIdentifier {
		return actual
	}
	symbol := l.symbol(node)
	if symbol == nil || node.FlowNodeData() == nil {
		return actual
	}
	declared := l.checker.GetTypeOfSymbol(symbol)
	if !l.arrayPredicateDomain(declared) && declared.Flags()&checker.TypeFlagsUnknown == 0 {
		return actual
	}
	flow := node.FlowNodeData().FlowNode
	for steps := 0; flow != nil && steps < 256; steps++ {
		if flow.Flags&(ast.FlowFlagsAssignment|ast.FlowFlagsLabel|ast.FlowFlagsCall) != 0 {
			return actual
		}
		if flow.Flags&ast.FlowFlagsCondition != 0 && flow.Node != nil && l.arrayPredicateFlowCall(flow.Node) {
			call := ast.SkipParentheses(flow.Node).AsCallExpression()
			if l.symbol(ast.SkipParentheses(call.Arguments.Nodes[0])) == symbol {
				return l.arrayPredicateMembers(declared, flow.Flags&ast.FlowFlagsTrueCondition != 0)
			}
		}
		flow = flow.Antecedent
	}
	return actual
}

// Indexed reads and their ?? result retain the recovered element contract,
// including the missing element required by noUncheckedIndexedAccess.
func (l *lowering) arrayPredicateObservedType(node *ast.Node) *checker.Type {
	node = ast.SkipParentheses(node)
	actual := l.checker.GetTypeAtLocation(node)
	if node.Kind == ast.KindIdentifier {
		return l.arrayPredicateType(node)
	}
	if actual.Flags()&checker.TypeFlagsAny == 0 {
		return actual
	}
	switch node.Kind {
	case ast.KindElementAccessExpression:
		array := l.arrayPredicateType(node.AsElementAccessExpression().Expression)
		if l.checker.IsArrayType(array) {
			element := l.checker.GetElementTypeOfArrayType(array)
			if element != nil && element.Flags()&checker.TypeFlagsAny == 0 {
				return l.checker.GetUnionType([]*checker.Type{element, l.checker.GetUndefinedType()})
			}
		}
	case ast.KindBinaryExpression:
		binary := node.AsBinaryExpression()
		if binary.OperatorToken.Kind == ast.KindQuestionQuestionToken {
			left := l.arrayPredicateObservedType(binary.Left)
			if left.Flags()&checker.TypeFlagsAny == 0 {
				return l.checker.GetUnionType([]*checker.Type{l.checker.GetNonNullableType(left), l.checker.GetTypeAtLocation(binary.Right)})
			}
		}
	}
	return actual
}

// The pinned checker owns construction of the readonly array type, just as it
// owns predicate flow facts. This introduces no any element contract.
//
//go:linkname predicateReadonlyArray github.com/microsoft/TypeScript/tsc/internal/checker.(*Checker).createArrayTypeEx
func predicateReadonlyArray(receiver *checker.Checker, element *checker.Type, readonly bool) *checker.Type

// A proven wrapper has the same arrayness test as the builtin. Its annotation
// cannot supply element facts missing from the caller's declared union.
func (l *lowering) arrayPredicateFlowCall(node *ast.Node) bool {
	if l.isArrayPredicateCall(node) {
		return true
	}
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindCallExpression {
		return false
	}
	call := node.AsCallExpression()
	if call.QuestionDotToken != nil || len(call.Arguments.Nodes) != 1 {
		return false
	}
	symbol := l.symbol(ast.SkipParentheses(call.Expression))
	if symbol == nil {
		return false
	}
	for _, declaration := range symbol.Declarations {
		if declaration.Kind != ast.KindFunctionDeclaration || len(declaration.Parameters()) != 1 || declaration.Body() == nil || declaration.Type() == nil || declaration.Type().Kind != ast.KindTypePredicate {
			continue
		}
		target := l.checker.GetTypeFromTypeNode(declaration.Type().AsTypePredicateNode().Type)
		if !checker.Checker_isTypeIdenticalTo(l.checker, target, predicateReadonlyArray(l.checker, l.checker.GetUnknownType(), true)) {
			continue
		}
		body := declaration.Body()
		if body.Kind != ast.KindBlock || len(body.AsBlock().Statements.Nodes) != 1 {
			continue
		}
		statement := body.AsBlock().Statements.Nodes[0]
		if statement.Kind != ast.KindReturnStatement || statement.AsReturnStatement().Expression == nil {
			continue
		}
		returned := ast.SkipParentheses(statement.AsReturnStatement().Expression)
		if l.isArrayPredicateCall(returned) && l.symbol(ast.SkipParentheses(returned.AsCallExpression().Arguments.Nodes[0])) == l.symbol(declaration.Parameters()[0].Name()) {
			return true
		}
	}
	return false
}

internal/lower/predicates.go:
package lower

import (
	"fmt"
	_ "unsafe"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/microsoft/TypeScript/tsc/shim/scanner"
)

// As in instantiate.go, this calls the pinned checker's own implementation until its shim
// exports it. The annotation is a claimed postcondition, never a flow fact. The flow nodes below contain
// only checks independently trusted by Adamic, not assertion calls or assignments.
//
//go:linkname predicateFlowType github.com/microsoft/TypeScript/tsc/internal/checker.(*Checker).getFlowTypeOfReferenceEx
func predicateFlowType(receiver *checker.Checker, reference *ast.Node, declared, initial *checker.Type, container *ast.Node, flow *ast.FlowNode) *checker.Type

type predicateFlowProof struct {
	l          *lowering
	function   *ast.Node
	parameter  *ast.Node
	declared   *checker.Type
	admitted   *checker.Type
	target     *checker.Type
	assertion  bool
	trueTypes  []*checker.Type
	lastReturn *ast.Node
}

type predicateFlowPath struct {
	flow    *ast.FlowNode
	checked bool
}

func (p *predicateFlowProof) refused(node *ast.Node, reason string) error {
	return &Refused{Where: p.l.program.Where(node), What: "a type predicate whose return is not proven (" + reason + ")", Fix: "inline the check where you use it, or return a discriminant comparison on the unmodified parameter (adamic/no-type-predicate)"}
}

func (l *lowering) proveFlowPredicate(node *ast.Node) error {
	if l.censusPredicateMarkerContract(node) {
		return nil
	}
	annotation := node.AsTypePredicateNode()
	function := node.Parent
	if !ast.IsFunctionLike(function) || function.Body() == nil || annotation.ParameterName.Kind != ast.KindIdentifier {
		return (&predicateFlowProof{l: l}).refused(node, "there is no body proving this parameter")
	}
	var parameter *ast.Node
	for _, candidate := range function.Parameters() {
		if ast.IsIdentifier(candidate.Name()) && candidate.Name().Text() == annotation.ParameterName.Text() {
			parameter = candidate
			break
		}
	}
	p := &predicateFlowProof{l: l, function: function, parameter: parameter, assertion: annotation.AssertsModifier != nil}
	if parameter == nil || parameter.AsParameterDeclaration().Initializer != nil || parameter.AsParameterDeclaration().DotDotDotToken != nil {
		return p.refused(node, "the predicate must name an unchanged plain parameter")
	}
	p.declared = l.checker.GetTypeAtLocation(parameter.Name())
	if annotation.Type != nil {
		p.target = l.checker.GetTypeFromTypeNode(annotation.Type)
	} else {
		// asserts cond is accepted only for a boolean parameter, with a proven true postcondition.
		if p.declared.Flags()&checker.TypeFlagsBooleanLike == 0 {
			return p.refused(node, "asserts cond needs a boolean parameter")
		}
		p.target = predicateTrueType(l.checker)
	}
	// A rebinding changes the value being tested, not the caller's argument. Include writes in
	// nested closures, even if the checker happens to retain a narrowing across their calls.
	var changed *ast.Node
	var visit ast.Visitor
	visit = func(current *ast.Node) bool {
		if current.Kind == ast.KindIdentifier && l.checker.GetSymbolAtLocation(current) == l.checker.GetSymbolAtLocation(parameter.Name()) && ast.IsAssignmentTarget(current) {
			changed = current
		}
		current.ForEachChild(visit)
		return false
	}
	function.Body().ForEachChild(visit)
	if changed != nil {
		return p.refused(changed, "the predicate parameter is assigned")
	}
	return p.proveBody(node)
}

func (p *predicateFlowProof) proveBody(node *ast.Node) error {
	function := p.function
	paths := []predicateFlowPath{{flow: &ast.FlowNode{Flags: ast.FlowFlagsStart}}}
	var remaining []predicateFlowPath
	var err error
	if function.Body().Kind == ast.KindBlock {
		remaining, err = p.statement(function.Body(), paths)
	} else {
		err = p.returned(function.Body(), function.Body(), paths)
	}
	if err != nil {
		return err
	}
	for _, path := range remaining {
		if !p.assertion {
			return p.refused(function.Body(), "implicit return is not a proven boolean")
		}
		if err := p.normalReturn(function.Body(), path); err != nil {
			return err
		}
	}
	if !p.assertion && len(p.trueTypes) > 0 && !checker.Checker_isTypeIdenticalTo(p.l.checker, p.l.checker.GetUnionType(p.trueTypes), p.target) {
		return p.refused(p.lastReturn, "the body's true narrowing does not match "+p.l.checker.TypeToString(p.target))
	}
	return nil
}

func (p *predicateFlowProof) narrowed(path predicateFlowPath, initial *checker.Type) *checker.Type {
	if path.flow.Node != nil && p.l.isArrayPredicateCall(path.flow.Node) && p.reference(ast.SkipParentheses(ast.SkipParentheses(path.flow.Node).AsCallExpression().Arguments.Nodes[0])) {
		return p.l.arrayPredicateMembers(initial, path.flow.Flags&ast.FlowFlagsTrueCondition != 0)
	}
	if p.admitted != nil && initial == p.declared {
		initial = p.admitted
	}
	return p.l.concrete(predicateFlowType(p.l.checker, p.parameter.Name(), p.declared, initial, p.function, path.flow))
}

func predicateBranch(path predicateFlowPath, expression *ast.Node, truth bool) predicateFlowPath {
	flags := ast.FlowFlagsFalseCondition
	if truth {
		flags = ast.FlowFlagsTrueCondition
	}
	return predicateFlowPath{flow: &ast.FlowNode{Flags: flags, Node: expression, Antecedent: path.flow}, checked: true}
}

// Immutable scalar arguments carry their admitted value type into the body.
// An object view does not certify its current tag without an actual test.
func (p *predicateFlowProof) admittedValueProof() bool {
	return p.admitted != nil && p.target.Flags()&(checker.TypeFlagsNumberLike|checker.TypeFlagsStringLike|checker.TypeFlagsBooleanLike|checker.TypeFlagsUndefined) != 0
}

func (p *predicateFlowProof) normalReturn(node *ast.Node, path predicateFlowPath) error {
	narrowed := p.narrowed(path, p.declared)
	if (!path.checked && !p.admittedValueProof()) || !checker.Checker_isTypeIdenticalTo(p.l.checker, narrowed, p.target) || p.l.nominalMismatch(narrowed, p.target, map[[2]*checker.Type]bool{}) != nil {
		return p.refused(node, "normal return has not narrowed "+p.parameter.Name().Text()+" to "+p.l.checker.TypeToString(p.target))
	}
	return nil
}

func (p *predicateFlowProof) returned(node, expression *ast.Node, paths []predicateFlowPath) error {
	p.lastReturn = node
	if p.assertion {
		if expression != nil {
			return p.refused(node, "an assertion must return without a value")
		}
		for _, path := range paths {
			if err := p.normalReturn(node, path); err != nil {
				return err
			}
		}
		return nil
	}
	if expression == nil {
		return p.refused(node, "return has no boolean check")
	}
	expression = ast.SkipParentheses(expression)
	literal := expression.Kind == ast.KindTrueKeyword || expression.Kind == ast.KindFalseKeyword
	if !literal && !p.check(expression) {
		return p.refused(node, "return expression is not a trusted check on "+p.parameter.Name().Text())
	}
	for _, path := range paths {
		for _, truth := range []bool{true, false} {
			if literal && truth != (expression.Kind == ast.KindTrueKeyword) {
				continue
			}
			branch := path
			if !literal {
				branch = predicateBranch(path, expression, truth)
			}
			// For a false path, an argument initially in the claimed type must be
			// impossible, as for inferred predicates. That proves the caller's else
			// narrowing independently of the true-return comparison.
			if truth {
				narrowed := p.narrowed(branch, p.declared)
				if (!branch.checked && !p.admittedValueProof()) || !p.l.checker.IsTypeAssignableTo(narrowed, p.target) || p.l.nominalMismatch(narrowed, p.target, map[[2]*checker.Type]bool{}) != nil {
					return p.refused(node, "true return narrows to "+p.l.checker.TypeToString(narrowed)+", not "+p.l.checker.TypeToString(p.target))
				}
				p.trueTypes = append(p.trueTypes, narrowed)
			} else if p.narrowed(branch, p.target).Flags()&checker.TypeFlagsNever == 0 {
				return p.refused(node, "false return can still contain "+p.l.checker.TypeToString(p.target))
			}
		}
	}
	return nil
}

func (p *predicateFlowProof) statement(node *ast.Node, paths []predicateFlowPath) ([]predicateFlowPath, error) {
	if len(paths) == 0 {
		return nil, nil
	}
	if len(paths) > 256 {
		return nil, p.refused(node, "too many return paths to prove")
	}
	switch node.Kind {
	case ast.KindBlock:
		for _, statement := range node.AsBlock().Statements.Nodes {
			var err error
			paths, err = p.statement(statement, paths)
			if err != nil {
				return nil, err
			}
		}
		return paths, nil
	case ast.KindIfStatement:
		statement := node.AsIfStatement()
		if !p.check(statement.Expression) {
			return nil, p.refused(node, "branch is not a trusted parameter check")
		}
		var then, otherwise []predicateFlowPath
		for _, path := range paths {
			then = append(then, predicateBranch(path, statement.Expression, true))
			otherwise = append(otherwise, predicateBranch(path, statement.Expression, false))
		}
		then, err := p.statement(statement.ThenStatement, then)
		if err != nil {
			return nil, err
		}
		if statement.ElseStatement != nil {
			otherwise, err = p.statement(statement.ElseStatement, otherwise)
			if err != nil {
				return nil, err
			}
		}
		return append(then, otherwise...), nil
	case ast.KindReturnStatement:
		return nil, p.returned(node, node.AsReturnStatement().Expression, paths)
	case ast.KindThrowStatement:
		return nil, nil
	case ast.KindEmptyStatement:
		return paths, nil
	case ast.KindExpressionStatement, ast.KindVariableStatement:
		if node.Kind == ast.KindExpressionStatement && p.l.isPanicCall(node.Expression()) {
			return nil, nil
		}
		if predicateEffects(node) {
			// Unknown calls and all writes can invalidate discriminants through an alias. Starting
			// over also prevents the checker from retaining stale readonly-property facts.
			for index := range paths {
				paths[index] = predicateFlowPath{flow: &ast.FlowNode{Flags: ast.FlowFlagsStart}}
			}
		}
		return paths, nil
	default:
		return nil, p.refused(node, fmt.Sprintf("return paths through %s are not verified", node.Kind))
	}
}

// check recognizes only independently trusted narrowing expressions, with no calls, aliases,
// casts or computed property accesses. The checker still decides what each branch proves.
func (p *predicateFlowProof) check(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindPrefixUnaryExpression && node.AsPrefixUnaryExpression().Operator == ast.KindExclamationToken {
		return p.check(node.AsPrefixUnaryExpression().Operand)
	}
	if p.assertion && p.target == predicateTrueType(p.l.checker) && p.reference(node) {
		return true
	}
	if p.l.isArrayPredicateCall(node) {
		return p.reference(ast.SkipParentheses(node.AsCallExpression().Arguments.Nodes[0])) && (p.l.arrayPredicateDomain(p.declared) || p.declared.Flags()&checker.TypeFlagsUnknown != 0)
	}
	if node.Kind != ast.KindBinaryExpression {
		return false
	}
	binary := node.AsBinaryExpression()
	switch binary.OperatorToken.Kind {
	case ast.KindAmpersandAmpersandToken, ast.KindBarBarToken:
		return p.check(binary.Left) && p.check(binary.Right)
	case ast.KindInstanceOfKeyword:
		if !p.reference(ast.SkipParentheses(binary.Left)) || binary.Right.Kind != ast.KindIdentifier {
			return false
		}
		symbol := p.l.checker.GetSymbolAtLocation(binary.Right)
		if symbol != nil && symbol.Flags&ast.SymbolFlagsAlias != 0 {
			symbol = p.l.checker.GetAliasedSymbol(symbol)
		}
		return symbol != nil && symbol.Flags&ast.SymbolFlagsClass != 0
	case ast.KindEqualsEqualsEqualsToken, ast.KindExclamationEqualsEqualsToken:
		return p.checkedValue(binary.Left) && p.literal(binary.Right) || p.checkedValue(binary.Right) && p.literal(binary.Left)
	}
	return false
}

func (p *predicateFlowProof) reference(node *ast.Node) bool {
	return node.Kind == ast.KindIdentifier && p.l.checker.GetSymbolAtLocation(node) == p.l.checker.GetSymbolAtLocation(p.parameter.Name())
}

func (p *predicateFlowProof) checkedValue(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if p.reference(node) {
		return true
	}
	if node.Kind == ast.KindTypeOfExpression {
		return p.reference(ast.SkipParentheses(node.AsTypeOfExpression().Expression))
	}
	return node.Kind == ast.KindPropertyAccessExpression && p.reference(ast.SkipParentheses(node.AsPropertyAccessExpression().Expression)) && node.Flags&ast.NodeFlagsOptionalChain == 0
}

func (p *predicateFlowProof) literal(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	switch node.Kind {
	case ast.KindStringLiteral, ast.KindNumericLiteral, ast.KindNullKeyword, ast.KindTrueKeyword, ast.KindFalseKeyword:
		return true
	case ast.KindIdentifier:
		return node.Text() == "undefined" && p.l.checker.GetSymbolAtLocation(node) == p.l.checker.GetUndefinedSymbol()
	}
	return false
}

func predicateEffects(node *ast.Node) bool {
	switch node.Kind {
	case ast.KindPropertyAccessExpression, ast.KindElementAccessExpression:
		// A property read may dispatch a getter through a structural view.
		return true
	case ast.KindCallExpression, ast.KindNewExpression, ast.KindBinaryExpression:
		if node.Kind != ast.KindBinaryExpression || ast.IsAssignmentOperator(node.AsBinaryExpression().OperatorToken.Kind) {
			return true
		}
	case ast.KindPostfixUnaryExpression, ast.KindFunctionDeclaration, ast.KindFunctionExpression, ast.KindArrowFunction:
		return true
	case ast.KindPrefixUnaryExpression:
		operator := node.AsPrefixUnaryExpression().Operator
		if operator == ast.KindPlusPlusToken || operator == ast.KindMinusMinusToken {
			return true
		}
	}
	return node.ForEachChild(predicateEffects)
}

func predicateTrueType(c *checker.Checker) *checker.Type {
	for _, member := range c.GetBooleanType().Types() {
		if member.AsLiteralType().Value() == true {
			return member
		}
	}
	panic("checker boolean type has no true member")
}

// The flow verifier keeps main's literal and nominal proofs. Body summaries add
// verified helpers and truthiness assertions; tag-only facts use checked views.
func (l *lowering) predicateRefusal(node *ast.Node) error {
	if node.Parent.Kind == ast.KindFunctionDeclaration && node.Parent.Body() == nil && l.censusImplementation(node.Parent) != nil {
		// TODO: .a refusal mode must prove the overload through its implementation
		// here and refuse an over-promising declaration. .ts keeps call-site checks.
		return nil
	}
	if l.predicateParameter(node) != nil {
		return nil
	}
	original := l.proveFlowPredicate(node)
	if original == nil {
		return nil
	}
	proof, err := l.provePredicate(node)
	if err != nil {
		return original
	}
	if proof.TaggedView {
		target := l.checker.GetTypeAtLocation(node.AsTypePredicateNode().Type)
		members := []*checker.Type{target}
		if target.Flags()&checker.TypeFlagsUnion != 0 {
			members = target.Types()
		}
		for _, member := range members {
			for _, property := range l.checker.GetPropertiesOfType(member) {
				if property.Flags&ast.SymbolFlagsOptional != 0 {
					return original
				}
			}
			if _, err := l.view(node, nil, member); err != nil {
				return err
			}
		}
	}
	return nil
}

// A signature on a plain function parameter is an argument contract. The call
// visitor proves the actual function body before admitting any invocation. Live
// contracts also need a closed set of direct callers; an uncalled declaration or
// an escaped function value supplies no producer proof for its callback.
func (l *lowering) predicateParameter(node *ast.Node) *ast.Node {
	signature := node.Parent
	if signature == nil || signature.Kind != ast.KindFunctionType || signature.Parent == nil || signature.Parent.Kind != ast.KindParameter {
		return nil
	}
	parameter := signature.Parent
	if parameter.AsParameterDeclaration().Initializer != nil || parameter.AsParameterDeclaration().DotDotDotToken != nil {
		return nil
	}
	function := parameter.Parent
	if function.Kind == ast.KindFunctionDeclaration && function.Body() == nil {
		implementation := l.censusImplementation(function)
		if implementation == nil {
			return nil
		}
		for index, candidate := range function.Parameters() {
			if candidate == parameter && index < len(implementation.Parameters()) {
				parameter = implementation.Parameters()[index]
				function = implementation
				break
			}
		}
	}
	if !ast.IsFunctionLike(function) || function.Body() == nil {
		return nil
	}
	symbol := l.checker.GetSymbolAtLocation(parameter.Name())
	changed := false
	var visit ast.Visitor
	visit = func(n *ast.Node) bool {
		if n.Kind == ast.KindIdentifier && l.checker.GetSymbolAtLocation(n) == symbol && ast.IsAssignmentTarget(n) {
			changed = true
		}
		n.ForEachChild(visit)
		return false
	}
	function.Body().ForEachChild(visit)
	if changed {
		return nil
	}
	// A bodyless overload's callback predicate is not the implementation's
	// contract when the implementation takes an ordinary boolean callback.
	if signature.Parent != parameter && parameter.Type() != nil && parameter.Type().Kind == ast.KindFunctionType && parameter.Type().Type() != nil && parameter.Type().Type().Kind != ast.KindTypePredicate {
		return parameter
	}
	if !l.predicateCallbackCallers(function, symbol) {
		return nil
	}
	return parameter
}

// Every producer is checked by predicateArguments before annotations are admitted.
// Keep that proof within direct calls, and do not let a callback escape its body.
func (l *lowering) predicateCallbackCallers(function *ast.Node, callback *ast.Symbol) bool {
	if function.Kind != ast.KindFunctionDeclaration || !ast.IsIdentifier(function.Name()) || ast.HasSyntacticModifier(function, ast.ModifierFlagsExport) {
		return false
	}
	owner := l.symbol(function.Name())
	if owner == nil {
		return false
	}
	found, safe := false, true
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if ast.IsIdentifier(node) && !ast.IsPartOfTypeNode(node) && !ast.IsDeclarationName(node) {
			symbol := l.symbol(node)
			if symbol == owner || symbol == callback {
				callee := node
				for callee.Parent != nil && callee.Parent.Kind == ast.KindParenthesizedExpression {
					callee = callee.Parent
				}
				call := callee.Parent
				safe = safe && call != nil && call.Kind == ast.KindCallExpression && call.AsCallExpression().Expression == callee
				if symbol == owner {
					found = true
				}
			}
		}
		node.ForEachChild(visit)
		return false
	}
	for _, file := range l.program.Files() {
		file.AsNode().ForEachChild(visit)
	}
	return found && safe
}

func (l *lowering) predicateArguments(node *ast.Node) error {
	signature := l.checker.GetResolvedSignature(node)
	if signature == nil {
		return nil
	}
	if overload := signature.Declaration(); overload != nil && overload.Kind == ast.KindFunctionDeclaration && overload.Body() == nil && overload.Type() != nil && overload.Type().Kind == ast.KindTypePredicate {
		callee := ast.SkipParentheses(node.AsCallExpression().Expression)
		if callee.Kind != ast.KindIdentifier || l.symbol(callee) != l.symbol(overload.Name()) {
			return l.notYet(node, "an indirect call of a checked predicate overload")
		}
	}
	for index, parameter := range signature.Parameters() {
		if index >= len(node.AsCallExpression().Arguments.Nodes) {
			continue
		}
		var contract *ast.Node
		for _, declaration := range parameter.Declarations {
			if declaration.Kind == ast.KindParameter && declaration.Type() != nil && declaration.Type().Kind == ast.KindFunctionType && declaration.Type().Type() != nil && declaration.Type().Type().Kind == ast.KindTypePredicate {
				contract = declaration.Type().Type()
			}
		}
		if contract == nil {
			continue
		}
		argument := ast.SkipParentheses(node.AsCallExpression().Arguments.Nodes[index])
		implementation := argument
		if argument.Kind == ast.KindIdentifier {
			symbol := l.symbol(argument)
			if symbol != nil {
				for _, declaration := range symbol.Declarations {
					if ast.IsFunctionLike(declaration) && declaration.Body() != nil {
						implementation = declaration
					}
					if declaration.Kind == ast.KindVariableDeclaration && declaration.AsVariableDeclaration().Initializer != nil {
						implementation = ast.SkipParentheses(declaration.AsVariableDeclaration().Initializer)
					}
				}
			}
		}
		failure := func() error {
			file := ast.GetSourceFileOfNode(argument)
			text := file.Text()[scanner.GetTokenPosOfNode(argument, file, false):argument.End()]
			return &Refused{Where: l.program.Where(argument), What: "an unproven predicate argument for parameter " + parameter.Name + " (argument " + fmt.Sprintf("%q", text) + ")", Fix: "pass a named function or arrow whose body proves both predicate branches; return a boolean and narrow at the caller (adamic/no-type-predicate)"}
		}
		if !ast.IsFunctionLike(implementation) || implementation.Body() == nil || (implementation.Type() != nil && implementation.Type().Kind != ast.KindTypePredicate) {
			return failure()
		}
		if argument.Kind == ast.KindIdentifier {
			symbol := l.symbol(argument)
			changed := false
			var writes ast.Visitor
			writes = func(n *ast.Node) bool {
				if n.Kind == ast.KindIdentifier && l.symbol(n) == symbol && ast.IsAssignmentTarget(n) {
					changed = true
				}
				n.ForEachChild(writes)
				return false
			}
			for _, file := range l.program.Files() {
				file.AsNode().ForEachChild(writes)
			}
			if changed {
				return failure()
			}
		}
		wanted := contract.AsTypePredicateNode()
		calls := l.checker.GetSignaturesOfType(l.checker.GetTypeOfSymbol(parameter), checker.SignatureKindCall)
		var target *checker.Type
		if len(calls) == 1 {
			if predicate := predicateOfSignature(l.checker, calls[0]); predicate != nil {
				target = predicate.Type()
			}
		}
		if wanted.Type == nil || target == nil {
			return failure()
		}
		if implementation.Type() == nil {
			if !l.proveInferredPredicate(implementation, target) {
				return failure()
			}
		} else {
			annotation := implementation.Type().AsTypePredicateNode()
			if annotation.Type == nil || !checker.Checker_isTypeIdenticalTo(l.checker, l.checker.GetTypeAtLocation(annotation.Type), target) {
				return failure()
			}
			if err := l.predicateRefusal(implementation.Type()); err != nil {
				return failure()
			}
		}
	}
	return nil
}

// The pinned checker resolves a predicate's target under overload type arguments.
// This recovers the claim to validate; it never supplies a body-proof fact.
//
//go:linkname predicateOfSignature github.com/microsoft/TypeScript/tsc/internal/checker.(*Checker).getTypePredicateOfSignature
func predicateOfSignature(receiver *checker.Checker, signature *checker.Signature) *checker.TypePredicate

// Keep reference identity aligned with the pinned checker's flow analysis,
// including dotted/indexed spellings and stable computed indices.
//
//go:linkname predicateMatchingReference github.com/microsoft/TypeScript/tsc/internal/checker.(*Checker).isMatchingReference
func predicateMatchingReference(receiver *checker.Checker, source, target *ast.Node) bool

internal/lower/cast_proof.go:
package lower

import (
	"reflect"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// The proof contains checker types only, so refusals precede representation lowering of unknown
// operands. Concrete generic instantiations are proved again when they are lowered.
type castProof struct {
	structuralView bool
	interfaceView  bool
	field          string
	allowed        []*checker.Type
	classes        []*checker.Type
}

const castRepair = "use a proven upcast, cast a discriminated object union with unique literal or enum tags to members or a sub-union, or downcast along nominal class ancestry (adamic/no-unchecked-cast)"

func (l *lowering) castAssignable(source, target *checker.Type) bool {
	return l.classAssignable(source, target) && l.enumAssignable(source, target) && l.widened(source, target, map[[2]*checker.Type]bool{}) == nil && l.castOptionalFields(source, target, map[[2]*checker.Type]bool{}) && l.optionalRelationFailure(source, target, nil, map[[2]*checker.Type]bool{}) == ""
}

// A structural view can hide an optional field of an incompatible type. Assignability permits
// adding that field back, but a cast cannot prove what the hidden field holds. Follow nested
// readonly views and callable results too; nominal class construction already proves its fields.
func (l *lowering) castOptionalFields(source, target *checker.Type, seen map[[2]*checker.Type]bool) bool {
	pair := [2]*checker.Type{source, target}
	if source == target || seen[pair] || isClassInstance(target) {
		return true
	}
	seen[pair] = true
	defer delete(seen, pair)
	if source.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range source.Types() {
			if !l.castOptionalFields(member, target, seen) {
				return false
			}
		}
		return true
	}
	if target.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range target.Types() {
			if l.checker.IsTypeAssignableTo(source, member) && l.castOptionalFields(source, member, seen) {
				return true
			}
		}
		return false
	}
	if !l.structured(source) || !l.structured(target) {
		return true
	}
	from, to := l.checker.GetSignaturesOfType(source, checker.SignatureKindCall), l.checker.GetSignaturesOfType(target, checker.SignatureKindCall)
	if len(from) == 1 && len(to) == 1 {
		if !l.castOptionalFields(l.checker.GetReturnTypeOfSignature(from[0]), l.checker.GetReturnTypeOfSignature(to[0]), seen) {
			return false
		}
		for index, parameter := range to[0].Parameters() {
			if index < len(from[0].Parameters()) && !l.castOptionalFields(l.checker.GetTypeOfSymbol(parameter), l.checker.GetTypeOfSymbol(from[0].Parameters()[index]), seen) {
				return false
			}
		}
		return true
	}
	if source.Flags()&checker.TypeFlagsObject != 0 && target.Flags()&checker.TypeFlagsObject != 0 && source.ObjectFlags()&checker.ObjectFlagsReference != 0 && target.ObjectFlags()&checker.ObjectFlagsReference != 0 {
		fromArguments, toArguments := l.checker.GetTypeArguments(source), l.checker.GetTypeArguments(target)
		for index, argument := range toArguments {
			if index < len(fromArguments) && !l.castOptionalFields(fromArguments[index], argument, seen) {
				return false
			}
		}
	}
	for _, property := range l.checker.GetPropertiesOfType(target) {
		inside := l.checker.GetPropertyOfType(source, property.Name)
		if inside == nil {
			if property.Flags&ast.SymbolFlagsOptional != 0 {
				return false
			}
			continue
		}
		if !l.castOptionalFields(l.checker.GetTypeOfSymbol(inside), l.checker.GetTypeOfSymbol(property), seen) {
			return false
		}
	}
	return true
}

func castMembers(proven *checker.Type) []*checker.Type {
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		return proven.Types()
	}
	return []*checker.Type{proven}
}

func (l *lowering) castProof(node *ast.Node) (castProof, error) {
	as := node.AsAsExpression()
	if as.Type.Kind == ast.KindTypeReference && ast.IsIdentifier(as.Type.AsTypeReferenceNode().TypeName) && as.Type.AsTypeReferenceNode().TypeName.Text() == "const" {
		return castProof{}, nil
	}
	source := l.concrete(l.checker.GetTypeAtLocation(as.Expression))
	target := l.concrete(l.checker.GetTypeAtLocation(node))
	refused := &Refused{Where: l.program.Where(node), What: "a cast the runtime can't check", Fix: castRepair}
	inner := ast.SkipParentheses(as.Expression)
	if inner.Kind == ast.KindAsExpression && l.checker.GetTypeAtLocation(inner).Flags()&checker.TypeFlagsUnknown != 0 {
		return castProof{}, refused
	}
	if source.Flags()&checker.TypeFlagsAny != 0 || target.Flags()&checker.TypeFlagsAny != 0 {
		return castProof{}, refused
	}
	members, targets := castMembers(source), castMembers(target)
	allClasses := true
	for _, member := range append(append([]*checker.Type{}, members...), targets...) {
		allClasses = allClasses && isClassInstance(member)
	}
	var upcastFailure error
	// A structural assignability result is only an upcast candidate. Nominal
	// downcasts may also look assignable, but still need their runtime identity check.
	if l.checker.IsTypeAssignableTo(source, target) || l.checker.IsTypeAssignableTo(l.checker.GetWidenedType(source), target) {
		err := l.provenRelation(node, as.Expression, l.checker.GetTypeAtLocation(node))
		if err == nil {
			return castProof{}, nil
		}
		rawSource, rawTarget := l.checker.GetTypeAtLocation(as.Expression), l.checker.GetTypeAtLocation(node)
		if !allClasses || l.optionalRelationFailure(rawSource, rawTarget, as.Expression, map[[2]*checker.Type]bool{}) != "" || l.freshOrWidened(as.Expression, rawSource, rawTarget) != nil {
			if reason, ok := err.(*Refused); ok {
				reason.Fix += "; " + castRepair
			}
			return castProof{}, err
		}
		if reason, ok := err.(*Refused); ok {
			reason.Fix += "; " + castRepair
		}
		upcastFailure = err
	}

	if !allClasses && l.checker.IsTypeAssignableTo(source, target) {
		if err := l.refuseWidening(node); err != nil {
			if reason, ok := err.(*Refused); ok {
				reason.Fix += "; " + castRepair
			}
			return castProof{}, err
		}
	}
	if allClasses {
		for _, wanted := range targets {
			related := false
			for _, member := range members {
				if l.castAssignable(wanted, member) && l.nominalAncestor(wanted, member, map[[2]*checker.Type]bool{}) {
					if !l.classCastArguments(member, wanted) {
						return castProof{}, refused
					}
					related = true
				}
				// An erased identity cannot distinguish incompatible arguments of the same
				// generic class, even if another source member provides a valid ancestor.
				if l.classView(member, l.classNodeFor(wanted)) != nil && !l.nominalAncestor(member, wanted, map[[2]*checker.Type]bool{}) {
					return castProof{}, refused
				}
			}
			if !related {
				if upcastFailure != nil {
					return castProof{}, upcastFailure
				}
				return castProof{}, refused
			}
		}
		return castProof{classes: targets}, nil
	}
	if source.Flags()&checker.TypeFlagsUnion == 0 {

		origins := len(l.result.ViewOrigins)
		defer func() { l.result.ViewOrigins = l.result.ViewOrigins[:origins] }()
		if checked, err := l.interfaceCast(node, ir.Read{Of: ir.Object}, source, target); checked != nil || err != nil {
			return castProof{interfaceView: checked != nil}, err
		}
		from, fromKnown := l.representation(source)
		to, toKnown := l.representation(target)
		if source.Flags()&checker.TypeFlagsObject != 0 && target.Flags()&checker.TypeFlagsObject != 0 && fromKnown && toKnown && from == ir.Object && to == ir.Object && !isClassInstance(target) && l.checker.IsTypeAssignableTo(target, source) && l.widened(target, source, map[[2]*checker.Type]bool{}) == nil && len(l.checker.GetIndexInfosOfType(target)) == 0 {
			return castProof{structuralView: true}, nil
		}

		return castProof{}, refused
	}
	if !l.castUnionWrites(source) {
		return castProof{}, refused
	}
	// Checking kind cannot prove a refinement of a member's payload or callback signature.
	for _, wanted := range targets {
		found := false
		for _, member := range members {
			if l.castAssignable(member, wanted) && l.castAssignable(wanted, member) {
				found = true
			}
		}
		if !found {
			return castProof{}, refused
		}
	}
	for _, property := range l.checker.GetPropertiesOfType(members[0]) {
		proof := castProof{field: property.Name}
		literals := []*checker.Type{}
		valid := true
		for _, member := range members {
			literal := l.fieldLiteral(member, proof.field)
			if literal == nil {
				valid = false
				break
			}
			// Enum aliases compare by runtime value, including aliases from different enums.
			for _, previous := range literals {
				mask := checker.TypeFlagsStringLiteral | checker.TypeFlagsNumberLiteral | checker.TypeFlagsBooleanLiteral
				if previous.Flags()&mask != literal.Flags()&mask || reflect.DeepEqual(previous.AsLiteralType().Value(), literal.AsLiteralType().Value()) {
					valid = false
				}
			}
			literals = append(literals, literal)
			if l.castAssignable(member, target) {
				proof.allowed = append(proof.allowed, literal)
			}
		}
		if valid && len(proof.allowed) > 0 {
			return proof, nil
		}
	}
	return castProof{}, refused
}

// Writing through a union view must not change a member's tag or narrow payload promise. A common
// mutable slot is safe only if everything the union can write fits every member that owns it.
func (l *lowering) castUnionWrites(source *checker.Type) bool {
	for _, property := range l.checker.GetPropertiesOfType(source) {
		if l.checker.IsReadonlySymbol(property) || property.Flags&ast.SymbolFlagsMethod != 0 {
			continue
		}
		written := l.checker.GetTypeOfSymbol(property)
		for _, member := range source.Types() {
			inside := l.checker.GetPropertyOfType(member, property.Name)
			if inside == nil || !l.castAssignable(written, l.checker.GetTypeOfSymbol(inside)) {
				return false
			}
		}
	}
	return true
}

// An erased identity proves no type arguments. Every target parameter must survive directly in
// the source ancestor's arguments, so that nominal invariance already fixes it. A Box<T> whose
// base is a nongeneric Animal is uncheckable; Box<number> and Box<string> have the same tag there.
func (l *lowering) classCastArguments(source, target *checker.Type) bool {
	declaration := l.classNodeFor(target)
	if declaration == nil || len(declaration.TypeParameters()) == 0 {
		return true
	}
	view := l.classView(l.checker.GetTypeAtLocation(declaration.Name()), l.classNodeFor(source))
	if view == nil {
		return false
	}
	arguments := l.checker.GetTypeArguments(view)
	for _, parameter := range declaration.TypeParameters() {
		proven := l.checker.GetTypeAtLocation(parameter.Name())
		found := false
		for _, argument := range arguments {
			if argument == proven {
				found = true
			}
		}
		if !found {
			return false
		}
	}
	return true
}

// Ordinary IR exposes the check to both backends and ownership analyses. The operand is one call
// argument; the helper only rereads its parameter, never the source expression.
func (l *lowering) checkedClassCast(node *ast.Node, value ir.Expression, targets []*checker.Type, message string) (ir.Expression, error) {
	identities := []int{}
	for _, target := range targets {
		declaration := l.classNodeFor(target)
		if declaration == nil || declaration.Kind != ast.KindClassDeclaration {
			return nil, &Refused{Where: l.program.Where(node), What: "a cast without a declared class identity", Fix: castRepair}
		}
		if len(declaration.TypeParameters()) > 0 {
			identities = append(identities, l.classIdentity(declaration))
		} else {
			instance, err := l.instantiate(declaration, target, node)
			if err != nil {
				return nil, err
			}
			identities = append(identities, instance.class)
		}
	}
	function := len(l.result.Functions)
	local := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "cast_value", Type: ir.Object, Function: function})
	read := ir.Read{Local: local, Of: ir.Object}
	var condition ir.Expression
	for _, identity := range identities {
		test := ir.InstanceOf{Value: read, Class: identity}
		if condition == nil {
			condition = test
		} else {
			condition = ir.Binary{Operator: ir.Or, Left: condition, Right: test}
		}
	}
	l.result.Functions = append(l.result.Functions, ir.Function{Name: "checked_class_cast", Parameters: []int{local}, Returns: ir.Object, Body: []ir.Statement{
		ir.If{Condition: condition, Then: []ir.Statement{ir.Return{Value: read}}},
		ir.Panic{Message: ir.StringConstant{Index: l.constant(message)}},
	}})
	return ir.Call{Function: function, Arguments: []ir.Expression{value}, Returns: ir.Object}, nil
}

internal/lower/cast.go:
package lower

import (
	"reflect"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// cast lowers value as T. as const and a cast to a type the value already has (an upcast) are the
// value itself. A downcast to members of a discriminated union is checked at runtime: the tag is
// there to read. Any other cast is a type the compiler would have to trust, and 0.1 refuses it
// (adamic/no-unchecked-cast).
func (l *lowering) cast(node *ast.Node) (ir.Expression, error) {
	as := node.AsAsExpression()
	proof, err := l.castProof(node)
	if err != nil {
		return nil, err
	}
	source := l.concrete(l.checker.GetTypeAtLocation(as.Expression))
	target := l.concrete(l.checker.GetTypeAtLocation(node))
	if !l.sameKeeping(source, target, map[[2]*checker.Type]bool{}) {
		return nil, l.notYet(node, "a cast that changes the runtime representation or ownership of a reference")
	}
	value, err := l.expression(as.Expression)
	if err != nil {
		return nil, err
	}
	if proof.structuralView {
		return l.structuralViewCast(node, value, source, target)
	}
	if proof.interfaceView {
		return l.interfaceCast(node, value, l.concrete(l.checker.GetTypeAtLocation(as.Expression)), l.concrete(l.checker.GetTypeAtLocation(node)))
	}
	if len(proof.allowed) == 0 && len(proof.classes) == 0 {
		return value, nil
	}
	refused := &Refused{Where: l.program.Where(node), What: "a cast without an object tag representation", Fix: castRepair}
	if value.Type() != ir.Object {
		return nil, refused
	}
	message := "cast failed: this " + l.checker.TypeToString(source) + " is not a " + l.checker.TypeToString(target)
	if len(proof.classes) > 0 {
		return l.checkedClassCast(node, value, proof.classes, message)
	}
	cast := ir.CheckedCast{Value: value, Field: proof.field, Message: message}
	for _, literal := range proof.allowed {
		allowed, fieldType, constant := l.literalConstant(literal)
		if !constant || (cast.FieldType != 0 && cast.FieldType != fieldType) {
			return nil, refused
		}
		cast.Allowed = append(cast.Allowed, allowed)
		cast.FieldType = fieldType
	}
	if _, err := l.view(node, value, target); err != nil {
		return nil, err
	}
	cast.CheckedFields = true
	return cast, nil
}

// fieldLiteral is a member's type for a field when it's a single literal ('Circle', 1, true), the
// kind of field a runtime check can read the member from.
func (l *lowering) fieldLiteral(member *checker.Type, field string) *checker.Type {
	for _, property := range l.checker.GetPropertiesOfType(member) {
		if property.Name != field {
			continue
		}
		fieldType := l.checker.GetTypeOfSymbol(property)
		if fieldType.Flags()&(checker.TypeFlagsStringLiteral|checker.TypeFlagsNumberLiteral|checker.TypeFlagsBooleanLiteral) != 0 {
			return fieldType
		}
	}
	return nil
}

// literalConstant is a literal type as a constant to compare a field with.
func (l *lowering) literalConstant(literal *checker.Type) (ir.Expression, ir.Type, bool) {
	flags := literal.Flags()
	switch {
	case flags&checker.TypeFlagsStringLiteral != 0:
		text, isText := literal.AsLiteralType().Value().(string)
		return ir.StringConstant{Index: l.constant(text)}, ir.String, isText
	case flags&checker.TypeFlagsNumberLiteral != 0:
		value := reflect.ValueOf(literal.AsLiteralType().Value())
		if value.Kind() != reflect.Float64 {
			return nil, 0, false
		}
		return ir.NumberConstant{Value: value.Float()}, ir.Number, true
	case flags&checker.TypeFlagsBooleanLiteral != 0:
		return ir.BooleanConstant{Value: l.checker.TypeToString(literal) == "true"}, ir.Boolean, true
	}
	return nil, 0, false
}

internal/lower/invariance.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/load"
)

// Mutable locations are invariant in 0.1 (docs/0.1.md, adamic/invariant-mutable): tsc relates an
// array's elements, a property and a map's values covariantly, so a Dog[] is accepted as an Animal[],
// and the wider name can then write a cat where the dogs are read. Stage 0 doesn't run cohere's lint,
// so it refuses the same views itself, before lowering: every place a value goes into a typed slot
// (an initializer, an assignment, an argument, a return, a literal's property or element), the value's
// type is walked against the slot's, all the way down, as the Weak view check walks them.
//
// At each mutable slot the wider side can write, what it writes must be something the narrower side
// can read: the slot's type in the target must be assignable to its type in the source. tsc proved
// the other direction when it accepted the site, so together the slot is invariant. A readonly slot
// only reads, and stays covariant.
//
// Two shapes reach a mutable array where tsc's relation can't be walked part by part, and each is
// judged as cohere's rule judges it (cohere 838c6516):
//   - A type parameter target (const pack: Pack = narrow, Narrow extends Pack extends Animal[]): what
//     Pack holds is no type to compare against until it's instantiated, so a type parameter whose
//     constraint can be written is one mutable slot, and only the parameter itself (or it narrowed,
//     as T & {}) fills it.
//   - An intersection with an array (Dog[] & { tag } into Animal[] & { tag }): its array, tuple and
//     container members are paired member by member, as well as its properties.

// widening is a view refused: the parts of the source and the target at the slot where the target can
// write what the source can't read.
type widening struct {
	source, target *checker.Type

	// readonlyField names a readonly field seen as a writable one, when that's the slot.
	readonlyField string
	enum          bool

	// parameter is a function's parameter of type source seen as taking target, which it can't.
	parameter bool
}

// widened finds the first mutable slot at which a value of type from, seen as type to, could be
// written something it can't hold, or returns nil.
func (l *lowering) widened(from *checker.Type, to *checker.Type, visited map[[2]*checker.Type]bool) *widening {
	from, to = l.withoutUndefined(from), l.withoutUndefined(to)
	if from == to || visited[[2]*checker.Type{from, to}] {
		return nil
	}
	visited[[2]*checker.Type{from, to}] = true
	if l.openNumericEnumType(to) {
		for _, member := range l.definedMembers(from) {
			if !l.enumAssignable(member, to) {
				return &widening{source: from, target: to, enum: true}
			}
		}
		return nil
	}
	if to.Flags()&checker.TypeFlagsNumberLiteral != 0 && l.openNumericEnumType(from) {
		return &widening{source: from, target: to, enum: true}
	}
	if members := l.definedMembers(from); len(members) > 1 {
		// A union is any one of its members, each seen as the target.
		for _, member := range members {
			if found := l.widened(member, to, visited); found != nil {
				return found
			}
		}
		return nil
	}
	if members := l.definedMembers(to); len(members) > 1 {
		// Seen as a union, a value is seen as each member it can be, and narrowing picks any of them
		// to write through.
		for _, member := range members {
			if !l.checker.IsTypeAssignableTo(from, member) {
				continue
			}
			if found := l.widened(from, member, visited); found != nil {
				return found
			}
		}
		return nil
	}
	if to.Flags()&checker.TypeFlagsTypeParameter != 0 {
		if l.narrowedFrom(from, to) {
			return nil
		}
		if constraint := l.checker.GetBaseConstraintOfType(to); constraint != nil && l.canWrite(constraint, map[*checker.Type]bool{}) {
			return &widening{source: from, target: to}
		}
		return nil
	}
	if from.Flags()&checker.TypeFlagsTypeParameter != 0 {
		// What it can be is what its constraint allows: seen as anything wider, it's that seen so.
		constraint := l.checker.GetBaseConstraintOfType(from)
		if constraint == nil {
			return nil
		}
		return l.widened(constraint, to, visited)
	}
	if !l.enumAssignable(from, to) {
		return &widening{source: from, target: to, enum: true}
	}
	if !l.structured(from) || !l.structured(to) {
		// A class instance target is walked as any object is: its fields are slots as a literal's
		// are, so Box<Dog> seen as Box<Animal>, or a plain object seen as a class, is judged by them.
		return nil
	}
	fromSignatures := l.checker.GetSignaturesOfType(from, checker.SignatureKindCall)
	toSignatures := l.checker.GetSignaturesOfType(to, checker.SignatureKindCall)
	if len(fromSignatures) > 0 && len(toSignatures) > 0 {
		// A function seen as another is handed the other's arguments, and its results are seen as
		// the other's: each a view of its own.
		if l.censusNeverRestSignature(toSignatures[0]) {
			if l.censusDiscardedMarkerPredicate(fromSignatures[0], toSignatures[0]) {
				return nil
			}
			source := l.checker.GetReturnTypeOfSignature(fromSignatures[0])
			target := l.checker.GetReturnTypeOfSignature(toSignatures[0])
			if !l.checker.IsTypeAssignableTo(source, target) {
				return &widening{source: source, target: target}
			}
			return l.widened(source, target, visited)
		}
		fromParameters, toParameters := fromSignatures[0].Parameters(), toSignatures[0].Parameters()
		for index := 0; index < len(fromParameters) && index < len(toParameters); index++ {
			takes, given := l.censusCallableParameterType(fromParameters[index]), l.censusCallableParameterType(toParameters[index])
			if !l.enumAssignable(given, takes) || !l.checker.IsTypeAssignableTo(given, takes) {
				// tsc relates a method's parameters both ways (method bivariance), so a method taking
				// a Dog can be seen as one taking any Animal, and handed a Cat.
				return &widening{source: takes, target: given, parameter: true}
			}
			if found := l.widened(given, takes, visited); found != nil {
				return found
			}
		}
		return l.widened(l.checker.GetReturnTypeOfSignature(fromSignatures[0]), l.checker.GetReturnTypeOfSignature(toSignatures[0]), visited)
	}
	fromContainers := l.containers(from)
	for _, viewed := range l.containers(to) {
		for _, inside := range fromContainers {
			if !l.sameContainer(inside, viewed) {
				continue
			}
			if found := l.widenedElements(inside, viewed, visited); found != nil {
				return found
			}
			break
		}
	}
	if to.Flags()&checker.TypeFlagsObject != 0 && len(l.containers(to)) > 0 {
		// An array, tuple, map or set: its elements are its slots, and its own properties (length,
		// size) are numbers on both sides.
		return nil
	}
	return l.widenedProperties(from, to, nil, false, visited)
}

// widenedProperties walks to's properties against from's, but those skip names: each field a slot
// to can write unless it's readonly, and each method a function view of its own. A copy's fields
// (fresh) are slots of their own, which nothing else writes, so only what they hold is walked.
func (l *lowering) widenedProperties(from *checker.Type, to *checker.Type, skip map[string]bool, fresh bool, visited map[[2]*checker.Type]bool) *widening {
	for _, viewed := range l.checker.GetPropertiesOfType(to) {
		inside := l.checker.GetPropertyOfType(from, viewed.Name)
		if inside == nil || skip[viewed.Name] {
			continue
		}
		source, target := l.checker.GetTypeOfSymbol(inside), l.checker.GetTypeOfSymbol(viewed)
		if viewed.Flags&ast.SymbolFlagsMethod != 0 || inside.Flags&ast.SymbolFlagsMethod != 0 {
			// A method isn't a slot anything writes, but what it returns and takes are views: the
			// program's own methods. The library's (an Iterable's, an array's own) are left to the
			// rules for the library's types, and a generic one has no one type to compare.
			if len(viewed.Declarations) == 0 || load.IsLibrary(ast.GetSourceFileOfNode(viewed.Declarations[0])) || l.generic(target) || l.generic(source) {
				continue
			}
			if found := l.widened(source, target, visited); found != nil {
				return found
			}
			continue
		}
		if !fresh && !l.checker.IsReadonlySymbol(viewed) && l.checker.IsReadonlySymbol(inside) {
			// tsc ignores readonly when it relates properties, so a readonly field, which may hold
			// something narrower than its type says (it's covariant), can be seen as a writable one,
			// and the wider type written into it. Only the identical type, which this walk never
			// enters, is the same field.
			return &widening{source: source, target: target, readonlyField: viewed.Name}
		}
		if !fresh && !l.checker.IsReadonlySymbol(viewed) && (!l.enumAssignable(target, source) || !l.checker.IsTypeAssignableTo(target, source)) {
			return &widening{source: source, target: target}
		}
		if found := l.widened(source, target, visited); found != nil {
			return found
		}
	}
	return nil
}

// generic reports whether a function type has a type parameter of its own.
func (l *lowering) generic(proven *checker.Type) bool {
	for _, signature := range l.checker.GetSignaturesOfType(proven, checker.SignatureKindCall) {
		if len(signature.TypeParameters()) > 0 {
			return true
		}
	}
	return false
}

// widenedElements walks an array's, a tuple's, a map's or a set's type arguments in from against
// to's, each a slot to can write unless it's read only.
func (l *lowering) widenedElements(from *checker.Type, to *checker.Type, visited map[[2]*checker.Type]bool) *widening {
	mutable := !l.isLibraryType(to, "ReadonlyArray", "ReadonlyMap", "ReadonlySet") && !(checker.IsTupleType(to) && to.TargetTupleType().IsReadonly())
	return l.widenedArguments(from, to, mutable, visited)
}

// widenedArguments is widenedElements with whether to's own slots can be written given: a fresh
// container's can't be written through anything else (freshValue).
func (l *lowering) widenedArguments(from *checker.Type, to *checker.Type, mutable bool, visited map[[2]*checker.Type]bool) *widening {
	fromArguments, toArguments := l.checker.GetTypeArguments(from), l.checker.GetTypeArguments(to)
	if checker.IsTupleType(from) && !checker.IsTupleType(to) && len(toArguments) == 1 {
		// A tuple seen as an array: every element of it is seen as the array's element.
		widenedTo := make([]*checker.Type, len(fromArguments))
		for index := range widenedTo {
			widenedTo[index] = toArguments[0]
		}
		toArguments = widenedTo
	}
	for index := 0; index < len(fromArguments) && index < len(toArguments); index++ {
		source, target := fromArguments[index], toArguments[index]
		if mutable && (!l.enumAssignable(target, source) || !l.checker.IsTypeAssignableTo(target, source)) {
			return &widening{source: source, target: target}
		}
		if found := l.widened(source, target, visited); found != nil {
			return found
		}
	}
	return nil
}

// containers is a type's arrays, tuples, maps and sets: itself, or its members that are, when it's an
// intersection.
func (l *lowering) containers(proven *checker.Type) []*checker.Type {
	members := []*checker.Type{proven}
	if proven.Flags()&checker.TypeFlagsIntersection != 0 {
		members = proven.Types()
	}
	var found []*checker.Type
	for _, member := range members {
		if member.Flags()&checker.TypeFlagsObject != 0 && member.ObjectFlags()&checker.ObjectFlagsReference != 0 &&
			(l.checker.IsArrayType(member) || checker.IsTupleType(member) || l.isLibraryType(member, "Map", "ReadonlyMap", "Set", "ReadonlySet")) {
			found = append(found, member)
		}
	}
	return found
}

// sameContainer reports whether two containers are the same kind, whose type arguments pair up: two
// arrays or tuples (readonly or not), two maps, or two sets.
func (l *lowering) sameContainer(from *checker.Type, to *checker.Type) bool {
	switch {
	case l.checker.IsArrayType(to) || checker.IsTupleType(to):
		return l.checker.IsArrayType(from) || checker.IsTupleType(from)
	case l.isLibraryType(to, "Map", "ReadonlyMap"):
		return l.isLibraryType(from, "Map", "ReadonlyMap")
	default:
		return l.isLibraryType(from, "Set", "ReadonlySet")
	}
}

// canWrite reports whether something can be written through a value of a type, at any depth: an
// array, tuple, map or set that isn't read only, or a property that isn't readonly, or one inside a
// readonly one.
func (l *lowering) canWrite(proven *checker.Type, visited map[*checker.Type]bool) bool {
	proven = l.withoutUndefined(proven)
	if proven == nil || visited[proven] || !l.structured(proven) || len(l.checker.GetSignaturesOfType(proven, checker.SignatureKindCall)) > 0 {
		return false
	}
	visited[proven] = true
	containers := l.containers(proven)
	for _, container := range containers {
		if !l.isLibraryType(container, "ReadonlyArray", "ReadonlyMap", "ReadonlySet") && !(checker.IsTupleType(container) && container.TargetTupleType().IsReadonly()) {
			return true
		}
		for _, element := range l.checker.GetTypeArguments(container) {
			if l.canWrite(element, visited) {
				return true
			}
		}
	}
	if proven.Flags()&checker.TypeFlagsObject != 0 && len(containers) > 0 {
		return false
	}
	for _, property := range l.checker.GetPropertiesOfType(proven) {
		if property.Flags&ast.SymbolFlagsMethod != 0 {
			continue
		}
		if !l.checker.IsReadonlySymbol(property) || l.canWrite(l.checker.GetTypeOfSymbol(property), visited) {
			return true
		}
	}
	return false
}

// narrowedFrom reports whether from is the type parameter to itself, or it narrowed: an intersection
// with it among its members (T & {}, what a check against undefined leaves).
func (l *lowering) narrowedFrom(from *checker.Type, to *checker.Type) bool {
	if from == to {
		return true
	}
	if from.Flags()&checker.TypeFlagsIntersection != 0 {
		for _, member := range from.Types() {
			if member == to {
				return true
			}
		}
	}
	return false
}

// structured reports whether a type has parts to walk: an object or an intersection.
func (l *lowering) structured(proven *checker.Type) bool {
	return proven.Flags()&(checker.TypeFlagsObject|checker.TypeFlagsIntersection) != 0
}

// withoutUndefined is a type with undefined taken out of it: the one type left, or the union itself
// when several are, whose members widened walks one by one (definedMembers).
func (l *lowering) withoutUndefined(proven *checker.Type) *checker.Type {
	if members := l.definedMembers(proven); len(members) == 1 {
		return members[0]
	}
	return proven
}

// definedMembers is a union's members but undefined, or the type itself when it isn't a union.
func (l *lowering) definedMembers(proven *checker.Type) []*checker.Type {
	if proven == nil {
		return nil
	}
	if proven.Flags()&checker.TypeFlagsUnion == 0 {
		return []*checker.Type{proven}
	}
	var members []*checker.Type
	for _, member := range proven.Types() {
		if member.Flags()&checker.TypeFlagsUndefined == 0 {
			members = append(members, member)
		}
	}
	return members
}

// isClassInstance is the instance side of a class, generic or not.
func isClassInstance(proven *checker.Type) bool {
	if proven.Flags()&checker.TypeFlagsObject == 0 {
		return false
	}
	if proven.ObjectFlags()&checker.ObjectFlagsClass != 0 {
		return true
	}
	return proven.ObjectFlags()&checker.ObjectFlagsReference != 0 && proven.Target() != nil && proven.Target().ObjectFlags()&checker.ObjectFlagsClass != 0
}

// viewSite reports whether an expression is a value going into a typed slot: an initializer (a
// variable's, a parameter's default, a class field's), the right of an assignment, an argument, a
// returned value, a literal's property (shorthand too) or element, or an arrow's expression body.
// Parentheses around it are the same site.
func viewSite(node *ast.Node) bool {
	for node.Parent != nil && node.Parent.Kind == ast.KindParenthesizedExpression {
		node = node.Parent
	}
	parent := node.Parent
	if parent == nil {
		return false
	}
	switch parent.Kind {
	case ast.KindVariableDeclaration:
		// A destructuring declaration without a type keeps nothing of the value: its names take the
		// types of its parts, and the pattern's own type (its fields any) is no view of it.
		declaration := parent.AsVariableDeclaration()
		if ast.IsBindingPattern(declaration.Name()) && declaration.Type == nil {
			return false
		}
		return declaration.Initializer == node
	case ast.KindBinaryExpression:
		binary := parent.AsBinaryExpression()
		return binary.OperatorToken.Kind == ast.KindEqualsToken && binary.Right == node
	case ast.KindCallExpression:
		return parent.AsCallExpression().Expression != node
	case ast.KindNewExpression:
		return parent.AsNewExpression().Expression != node
	case ast.KindReturnStatement, ast.KindArrayLiteralExpression:
		return true
	case ast.KindPropertyAssignment:
		return parent.AsPropertyAssignment().Initializer == node
	case ast.KindParameter:
		return parent.AsParameterDeclaration().Initializer == node
	case ast.KindPropertyDeclaration:
		return parent.AsPropertyDeclaration().Initializer == node
	case ast.KindArrowFunction:
		return parent.AsArrowFunction().Body == node
	}
	return false
}

// refuseWidening refuses a value seen through a type that can write what it can't hold.
func (l *lowering) refuseWidening(node *ast.Node) error {
	if l.nodeFSFileReadOnlyArgument(node) || l.regexCallbackIntrinsicView(node) {
		return nil
	}
	var own, contextual *checker.Type
	var found *widening
	switch {
	case node.Kind == ast.KindAsExpression:
		as := node.AsAsExpression()
		if as.Type.Kind == ast.KindTypeReference && ast.IsIdentifier(as.Type.AsTypeReferenceNode().TypeName) && as.Type.AsTypeReferenceNode().TypeName.Text() == "const" {
			return nil
		}
		source, target := l.checker.GetTypeAtLocation(as.Expression), l.checker.GetTypeAtLocation(node)
		if l.checker.IsTypeAssignableTo(source, target) || l.checker.IsTypeAssignableTo(l.checker.GetWidenedType(source), target) {
			return l.provenRelation(node, as.Expression, target)
		}
		// Preserve the existing checks on downcasts; their lowering belongs to cast.go.
		own, contextual = source, target
		found = l.freshOrWidened(as.Expression, own, contextual)
	case node.Kind == ast.KindSatisfiesExpression:
		satisfies := node.AsSatisfiesExpression()
		return l.provenRelation(node, satisfies.Expression, l.checker.GetTypeAtLocation(satisfies.Type))
	case node.Kind == ast.KindShorthandPropertyAssignment:
		// { pets } is { pets: pets }: the variable seen as the literal's property.
		literal := l.checker.GetContextualType(node.Parent, checker.ContextFlagsNone)
		if literal == nil {
			return nil
		}
		property := l.checker.GetPropertyOfType(literal, node.Name().Text())
		if property == nil {
			return nil
		}
		own, contextual = l.checker.GetTypeAtLocation(node.Name()), l.checker.GetTypeOfSymbol(property)
		found = l.freshOrWidened(node.Name(), own, contextual)
	case node.Kind == ast.KindSpreadAssignment:
		// { ...kennel } copies kennel's fields, not what they hold: each field not written again after
		// it is kennel's value seen as the literal's field.
		literal := l.checker.GetContextualType(node.Parent, checker.ContextFlagsNone)
		if literal == nil {
			return nil
		}
		skip := map[string]bool{}
		after := false
		for _, property := range node.Parent.AsObjectLiteralExpression().Properties.Nodes {
			if property == node {
				after = true
			} else if after && property.Name() != nil {
				skip[property.Name().Text()] = true
			}
		}
		own, contextual = l.checker.GetTypeAtLocation(node.AsSpreadAssignment().Expression), literal
		found = l.widenedProperties(own, literal, skip, true, map[[2]*checker.Type]bool{})
	default:
		if node.Kind == ast.KindParenthesizedExpression || !l.isExpression(node) {
			return nil
		}
		if l.genericFunction(node) {
			// same<Item> written where a (value: number) => number goes is instantiated to exactly
			// that type, Item = number, so there's no wider view of it to judge.
			return nil
		}
		if pattern := destructuringTarget(node); pattern != nil {
			// [a, b] = tuple keeps nothing of the pattern: each element is read out and stored into
			// its name, so each element is the view, seen as its name's type, and the pattern isn't one.
			return l.refuseElementWidening(node, pattern)
		}
		if viewSite(node) {
			contextual = l.checker.GetContextualType(node, checker.ContextFlagsNone)
		}
		if contextual == nil {
			// With no type written for it, a value can still be taken into a wider one tsc made: the
			// union of a conditional's branches reduced to the wider (flag ? dogs : animals is an
			// Animal[]), a literal's elements likewise, a function's returns likewise.
			contextual = l.impliedTarget(node)
		}
		if contextual == nil {
			return nil
		}
		own = l.checker.GetTypeAtLocation(node)
		found = l.freshOrWidened(node, own, contextual)
	}
	if found == nil {
		return nil
	}
	return l.wideningRefusal(node, own, contextual, found)
}

func (l *lowering) wideningRefusal(node *ast.Node, own, contextual *checker.Type, found *widening) error {
	if found.enum {
		if enumObjectSymbol(found.target) != nil {
			return &Refused{Where: l.program.Where(node), What: "a structural object seen as " + l.checker.TypeToString(found.target) + "; the complete enum shape is unproven", Fix: "use the enum's runtime object or a typeof alias, or give the ordinary object an explicit interface"}
		}
		if l.flagEnum(l.enumIdentity(found.target)) && !l.numericEnum(l.enumIdentity(found.target)) {
			return l.flagWriteRefusal(node, found.target)
		}
		if l.numericEnum(l.enumIdentity(found.target)) || l.numericEnum(l.enumIdentity(found.source)) {
			return &Refused{Where: l.program.Where(node), What: "an unproven value assigned to a numeric literal or enum member slot " + l.checker.TypeToString(found.target), Fix: "compare with this literal and return that constant, or widen the slot to the whole numeric enum or number (adamic/enum-literal)"}
		}
		return &Refused{Where: l.program.Where(node), What: "an arbitrary number or a value from another enum assigned to " + l.checker.TypeToString(found.target) + "; its members are a closed union", Fix: "use a declared member of this enum, or compare the number with its members and return the matching member (adamic/enum-members)"}
	}
	what := "a value of type " + l.checker.TypeToString(own) + " seen as " + l.checker.TypeToString(contextual) + ", which can write " + l.checker.TypeToString(found.target) + " where " + l.checker.TypeToString(found.source) + " is read"
	fix := "make the wider type readonly (readonly T[], ReadonlyMap, readonly fields), which can't write; or copy the value ([...items], { ...item }) (adamic/invariant-mutable)"
	if found.parameter {
		what = "a function taking " + l.checker.TypeToString(found.source) + " seen as one taking " + l.checker.TypeToString(found.target) + " (tsc relates a method's parameters both ways), so it can be handed what it can't take"
		fix = "write the method as a property holding a function (handle: (animal: Animal) => void), which tsc checks one way, or take the wider type in the method (method-signature-style)"
	}
	if found.readonlyField != "" {
		what = "a value of type " + l.checker.TypeToString(own) + " seen as " + l.checker.TypeToString(contextual) + ", whose readonly field " + found.readonlyField + " becomes writable: a readonly field may hold something narrower than " + l.checker.TypeToString(found.source) + ", which a write of " + l.checker.TypeToString(found.target) + " would replace"
		fix = "keep " + found.readonlyField + " readonly in the type it's seen as, or copy the value ({ ...value }) (adamic/invariant-mutable)"
	}
	if found.target.Flags()&checker.TypeFlagsTypeParameter != 0 {
		what = "a value of type " + l.checker.TypeToString(found.source) + " seen as " + l.checker.TypeToString(found.target) + ", a type parameter whose constraint " + l.checker.TypeToString(l.checker.GetBaseConstraintOfType(found.target)) + " can be written, so it can write what " + l.checker.TypeToString(found.source) + " can't hold"
		fix = "take it as " + l.checker.TypeToString(found.source) + ", or constrain " + l.checker.TypeToString(found.target) + " to something readonly, which can't write (adamic/invariant-mutable)"
	}
	return &Refused{Where: l.program.Where(node), What: what, Fix: fix}
}

// freshOrWidened is widened for a value at a site, but a fresh one: a container made right there and
// held by nothing else (freshValue) can't be written through another name, so its own slots are
// covariant, and only what's inside it, held elsewhere too, is walked as a view.
func (l *lowering) freshOrWidened(node *ast.Node, own *checker.Type, contextual *checker.Type) *widening {
	node = ast.SkipParentheses(node)
	// A numeric enum read narrowed to never has a non-returning IR check at this exact site.
	// It cannot write a value into the contextual slot, including a closed string-enum slot.
	if own.Flags()&checker.TypeFlagsNever != 0 && l.enumNeverIdentity(node, map[*ast.Node]bool{}) != nil {
		return nil
	}
	targetLiteral := (contextual.Flags()&checker.TypeFlagsNumberLiteral != 0 || l.numericEnum(l.enumIdentity(contextual))) && !l.openNumericEnumType(contextual)
	if targetLiteral {
		if declared := l.enumStoredType(node); declared != nil {
			if l.openNumericEnumType(declared) && !l.enumMemberOrigin(node, l.enumIdentity(declared), map[*ast.Node]bool{}) {
				return &widening{source: declared, target: contextual, enum: true}
			}
		}
	}
	if found := l.flagMemberWidened(node, contextual); found != nil && !l.numericEnum(l.enumIdentity(found.target)) {
		return found
	}
	if target := l.flagTarget(contextual); target != nil && l.flagDomain(node, target) {
		return nil
	}
	switch node.Kind {
	case ast.KindObjectLiteralExpression, ast.KindArrayLiteralExpression:
		// Made as the type it's written into, held by nothing else: its own parts are sites.
		return nil
	case ast.KindConditionalExpression:
		// Either branch is the value: each judged as it is.
		conditional := node.AsConditionalExpression()
		for _, branch := range []*ast.Node{conditional.WhenTrue, conditional.WhenFalse} {
			if found := l.freshOrWidened(branch, l.checker.GetTypeAtLocation(branch), contextual); found != nil {
				return found
			}
		}
		return nil
	}
	visited := map[[2]*checker.Type]bool{}
	if !l.freshValue(node) {
		return l.widened(own, contextual, visited)
	}
	own, contextual = l.withoutUndefined(own), l.withoutUndefined(contextual)
	for _, viewed := range l.containers(contextual) {
		for _, inside := range l.containers(own) {
			if l.sameContainer(inside, viewed) {
				return l.widenedArguments(inside, viewed, false, visited)
			}
		}
	}
	return l.widened(own, contextual, visited)
}

// freshValue reports whether an expression makes a container nothing else holds: a copy (slice,
// filter, map, concat, Array.from) or a new Map, Set or Array.
func (l *lowering) freshValue(node *ast.Node) bool {
	switch node.Kind {
	case ast.KindNewExpression:
		callee := node.AsNewExpression().Expression
		return l.isLibraryGlobal(callee, "Map") || l.isLibraryGlobal(callee, "Set") || l.isLibraryGlobal(callee, "Array")
	case ast.KindCallExpression:
		callee := ast.SkipParentheses(node.AsCallExpression().Expression)
		if callee.Kind != ast.KindPropertyAccessExpression {
			return false
		}
		access := callee.AsPropertyAccessExpression()
		method := access.Name().Text()
		if method == "from" {
			return l.isLibraryGlobal(access.Expression, "Array")
		}
		switch method {
		case "slice", "filter", "map", "concat":
			return l.checker.IsArrayType(l.checker.GetTypeAtLocation(access.Expression)) || l.isLibraryType(l.checker.GetTypeAtLocation(access.Expression), "ReadonlyArray")
		}
	}
	return false
}

// isExpression reports whether a node is one a value can be: anything but a statement, a declaration,
// a name being declared or a type.
func (l *lowering) isExpression(node *ast.Node) bool {
	return ast.IsExpression(node) && !ast.IsPartOfTypeNode(node)
}

// impliedTarget is the type tsc gave what a value with no type written for it goes into, or nil: a
// conditional's (or ??'s, ||'s, &&'s) own type for its branches, an array literal's element type for
// its elements, and a function's inferred result for what it returns.
func (l *lowering) impliedTarget(node *ast.Node) *checker.Type {
	child := node
	for child.Parent != nil && child.Parent.Kind == ast.KindParenthesizedExpression {
		child = child.Parent
	}
	parent := child.Parent
	if parent == nil {
		return nil
	}
	switch parent.Kind {
	case ast.KindConditionalExpression:
		if conditional := parent.AsConditionalExpression(); conditional.WhenTrue == child || conditional.WhenFalse == child {
			return l.checker.GetTypeAtLocation(parent)
		}
	case ast.KindBinaryExpression:
		switch parent.AsBinaryExpression().OperatorToken.Kind {
		case ast.KindQuestionQuestionToken, ast.KindBarBarToken, ast.KindAmpersandAmpersandToken:
			return l.checker.GetTypeAtLocation(parent)
		}
	case ast.KindArrayLiteralExpression:
		literal := l.checker.GetTypeAtLocation(parent)
		if l.checker.IsArrayType(literal) {
			if arguments := l.checker.GetTypeArguments(literal); len(arguments) == 1 {
				return arguments[0]
			}
		}
	case ast.KindReturnStatement, ast.KindArrowFunction:
		if parent.Kind == ast.KindArrowFunction && parent.AsArrowFunction().Body != child {
			return nil
		}
		function := parent
		for function != nil && !ast.IsFunctionLike(function) {
			function = function.Parent
		}
		if function == nil {
			return nil
		}
		return l.checker.GetReturnTypeOfSignature(l.checker.GetSignatureFromDeclaration(function))
	}
	return nil
}

// destructuringTarget is the array pattern a value is assigned into, [a, b] = value, or nil.
func destructuringTarget(node *ast.Node) *ast.Node {
	for node.Parent != nil && node.Parent.Kind == ast.KindParenthesizedExpression {
		node = node.Parent
	}
	if parent := node.Parent; parent != nil && parent.Kind == ast.KindBinaryExpression {
		binary := parent.AsBinaryExpression()
		if binary.OperatorToken.Kind == ast.KindEqualsToken && binary.Right == node && binary.Left.Kind == ast.KindArrayLiteralExpression {
			return binary.Left
		}
	}
	return nil
}

// refuseElementWidening refuses [a, b] = tuple when an element is seen through its name's type as
// a view that can write what the element can't hold: [animals] = [dogs] puts a Dog[] in an
// Animal[]. A value that isn't a tuple is judged whole, as anywhere.
func (l *lowering) refuseElementWidening(node *ast.Node, pattern *ast.Node) error {
	own := l.checker.GetTypeAtLocation(node)
	if !checker.IsTupleType(own) {
		contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone)
		if contextual == nil {
			return nil
		}
		if found := l.widened(own, contextual, map[[2]*checker.Type]bool{}); found != nil {
			return &Refused{Where: l.program.Where(node), What: "a value of type " + l.checker.TypeToString(own) + " seen as " + l.checker.TypeToString(contextual) + ", which can write " + l.checker.TypeToString(found.target) + " where " + l.checker.TypeToString(found.source) + " is read", Fix: "make the wider type readonly (readonly T[], ReadonlyMap, readonly fields), which can't write; or copy the value ([...items], { ...item }) (adamic/invariant-mutable)"}
		}
		return nil
	}
	elements := l.checker.GetTypeArguments(own)
	for index, target := range pattern.AsArrayLiteralExpression().Elements.Nodes {
		if index >= len(elements) || target.Kind == ast.KindOmittedExpression {
			continue
		}
		to := l.checker.GetTypeAtLocation(target)
		if found := l.widened(elements[index], to, map[[2]*checker.Type]bool{}); found != nil {
			return &Refused{Where: l.program.Where(target), What: "a value of type " + l.checker.TypeToString(elements[index]) + " seen as " + l.checker.TypeToString(to) + ", which can write " + l.checker.TypeToString(found.target) + " where " + l.checker.TypeToString(found.source) + " is read", Fix: "make the wider type readonly (readonly T[], ReadonlyMap, readonly fields), which can't write; or copy the value ([...items], { ...item }) (adamic/invariant-mutable)"}
		}
	}
	return nil
}

// genericFunction reports whether an expression is a function with type parameters of its own,
// which tsc instantiates to the type it's written into rather than viewing it through that type.
func (l *lowering) genericFunction(node *ast.Node) bool {
	for _, signature := range l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(node), checker.SignatureKindCall) {
		if len(signature.TypeParameters()) > 0 {
			return true
		}
	}
	return false
}

internal/lower/census_small.go:
package lower

import (
	"fmt"
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// censusRestParameter admits rest only where every call passes a freshly packed array.
// Function values and methods have a different calling convention and remain NotYet.
func (l *lowering) censusRestParameter(declaration, parameter *ast.Node) error {
	if declaration.Kind != ast.KindFunctionDeclaration || len(declaration.TypeParameters()) != 0 {
		return l.notYet(parameter, "a rest parameter outside a nongeneric named function")
	}
	if l.result.Functions[l.functionIndex].Closure {
		return l.notYet(parameter, "a rest parameter in a named closure")
	}
	parameters := declaration.Parameters()
	if parameters[len(parameters)-1] != parameter {
		return l.notYet(parameter, "a rest parameter before another parameter")
	}
	proven := l.checker.GetTypeAtLocation(parameter.Name())
	if !l.checker.IsArrayType(proven) {
		return l.notYet(parameter, "a rest parameter other than an array")
	}
	element, known := l.kept(l.checker.GetElementTypeOfArrayType(proven))
	if !known || slotless(element) {
		return l.notYet(parameter, "a rest array of "+l.checker.TypeToString(proven))
	}
	return nil
}

// censusRestDeclaration recovers the declaration without adding state to lower.go.
func (l *lowering) censusRestDeclaration(function int) *ast.Node {
	for symbol, index := range l.functions {
		if index != function {
			continue
		}
		for _, declaration := range symbol.Declarations {
			if declaration.Kind != ast.KindFunctionDeclaration || declaration.Body() == nil {
				continue
			}
			parameters := declaration.Parameters()
			if len(parameters) > 0 && parameters[len(parameters)-1].AsParameterDeclaration().DotDotDotToken != nil {
				return declaration
			}
		}
	}
	return nil
}

// censusRestCall evaluates fixed arguments before rest items, and copies each spread
// when encountered. The array is new even when the only item is a spread.
func (l *lowering) censusRestCall(call *ast.CallExpression, function int, declaration *ast.Node) (ir.Expression, error) {
	parameters := declaration.Parameters()
	fixed := len(parameters) - 1
	proven := l.checker.GetTypeAtLocation(parameters[fixed].Name())
	element, _ := l.kept(l.checker.GetElementTypeOfArrayType(proven))
	rest := ir.ArrayLiteral{Element: element}
	arguments := []ir.Expression{}
	for index, argument := range call.Arguments.Nodes {
		spread := argument.Kind == ast.KindSpreadElement
		valueNode := argument
		if spread {
			if index < fixed {
				return nil, l.notYet(argument, "a spread filling fixed parameters before a rest parameter")
			}
			valueNode = argument.AsSpreadElement().Expression
		}
		value, err := l.expression(valueNode)
		if err != nil {
			return nil, err
		}
		if index < fixed {
			arguments = append(arguments, value)
			continue
		}
		if spread {
			source := l.checker.GetTypeAtLocation(valueNode)
			if !l.checker.IsArrayType(source) {
				return nil, l.notYet(argument, "a rest spread other than an array")
			}
			held, known := l.kept(l.checker.GetElementTypeOfArrayType(source))
			if !known || held != element {
				return nil, l.notYet(argument, "a rest spread with differently held elements")
			}
		} else {
			value = fit(value, element)
			if value.Type() != element {
				return nil, l.notYet(argument, "a rest argument with another representation")
			}
		}
		rest.Elements = append(rest.Elements, value)
		rest.Spread = append(rest.Spread, spread)
	}
	// Missing fixed arguments must keep their positions before the rest array.
	for len(arguments) < fixed {
		of := l.result.Locals[l.result.Functions[function].Parameters[len(arguments)]].Type
		if !of.IsMaybe() && !of.IsReference() {
			return nil, l.notYet(parameters[len(arguments)], "a missing fixed argument before rest")
		}
		arguments = append(arguments, fit(ir.Undefined{}, of))
	}
	arguments = append(arguments, rest)
	return l.censusOverloadResult(call, ir.Call{Function: function, Arguments: arguments, Returns: l.result.Functions[function].Returns})
}

// Boolean fields have a tagged byte; other slotless representations remain refused.
func censusFieldSlotless(of ir.Type) bool {
	return slotless(of) && of != ir.MaybeBoolean && of != ir.Union
}

// Only the implementation of a named overload set has executable code.
func (l *lowering) censusImplementation(declaration *ast.Node) *ast.Node {
	if declaration.Kind != ast.KindFunctionDeclaration || declaration.Name() == nil {
		return nil
	}
	symbol := l.symbol(declaration.Name())
	if symbol == nil {
		return nil
	}
	for _, candidate := range symbol.Declarations {
		if candidate.Kind == ast.KindFunctionDeclaration && candidate.Body() != nil {
			return candidate
		}
	}
	return nil
}

// Use the same nominal, invariant and strictly contravariant relation as class overrides.
func (l *lowering) censusRelated(from, to *checker.Type) bool {
	from, to = l.concrete(from), l.concrete(to)
	return l.classAssignable(from, to) && l.widened(from, to, map[[2]*checker.Type]bool{}) == nil
}

func (l *lowering) censusOverloads(implementation *ast.Node) error {
	if implementation.Kind != ast.KindFunctionDeclaration || implementation.Body() == nil {
		return nil
	}
	symbol := l.symbol(implementation.Name())
	if symbol == nil {
		return nil
	}
	ordinal := 0
	for _, overload := range symbol.Declarations {
		if overload.Kind != ast.KindFunctionDeclaration || overload.Body() != nil {
			continue
		}
		ordinal++
		if err := l.censusOverload(implementation, overload, ordinal); err != nil {
			return err
		}
	}
	return nil
}

// Compare generic signatures under the same rigid type parameters, never under one
// lucky runtime instantiation. Mapping the implementation's binders is alpha-renaming.
func (l *lowering) censusOverload(implementation, overload *ast.Node, ordinal int) error {
	label := fmt.Sprintf("overload %d of %s", ordinal, implementation.Name().Text())
	declaredTypes, servedTypes := overload.TypeParameters(), implementation.TypeParameters()
	outerMapper := l.typeMapper
	defer func() { l.typeMapper = outerMapper }()
	if len(servedTypes) > 0 {
		sources, targets := []*checker.Type{}, []*checker.Type{}
		inferred := map[*checker.Type]*checker.Type{}
		if len(servedTypes) > len(declaredTypes) {
			// Extra binders need a witness from the entire signature, not positional
			// alpha-renaming: implementations may insert a binder before an old one.
			for index, parameter := range implementation.Parameters() {
				if index < len(overload.Parameters()) {
					l.inferTypes(l.checker.GetTypeAtLocation(parameter), l.checker.GetTypeAtLocation(overload.Parameters()[index]), inferred)
				}
			}
			l.inferTypes(l.checker.GetReturnTypeOfSignature(l.checker.GetSignatureFromDeclaration(implementation)), l.checker.GetReturnTypeOfSignature(l.checker.GetSignatureFromDeclaration(overload)), inferred)
		}
		for index, parameter := range servedTypes {
			source := l.checker.GetTypeAtLocation(parameter.Name())
			target := inferred[source]
			if len(servedTypes) <= len(declaredTypes) {
				target = l.checker.GetTypeAtLocation(declaredTypes[index].Name())
			} else if target == nil {
				// A binder with no evidence can use bottom as a candidate witness.
				// This is not permission to erase it: every constraint, incoming
				// parameter and outgoing result below must still hold for that witness.
				target = l.checker.GetNonNullableType(l.checker.GetUndefinedType())
			}
			sources = append(sources, source)
			targets = append(targets, target)
		}
		l.typeMapper = newTypeMapper(sources, targets)
		for index, parameter := range servedTypes {
			if constraint := l.checker.GetBaseConstraintOfType(sources[index]); constraint != nil && !l.censusRelated(targets[index], constraint) {
				where, name := overload, "type "+l.checker.TypeToString(targets[index])
				if len(servedTypes) <= len(declaredTypes) {
					where, name = declaredTypes[index], "type parameter "+declaredTypes[index].Name().Text()
				}
				return &Refused{Where: l.program.Where(where), What: label + " " + name + " cannot satisfy implementation parameter " + parameter.Name().Text(), Fix: "make implementation constraints accept every type admitted by the overload"}
			}
		}
	}
	declared, served := overload.Parameters(), implementation.Parameters()
	for index := 0; index <= max(len(declared), len(served)); index++ {
		given, parameter, givenRest, err := l.censusOverloadParameter(declared, index)
		if err != nil {
			return l.notYet(overload, label+" with a non-array rest parameter")
		}
		takes, actual, takesRest, err := l.censusOverloadParameter(served, index)
		if err != nil {
			return l.notYet(overload, label+" with a non-array implementation rest parameter")
		}
		if actual == nil {
			continue
		} // JavaScript evaluates and ignores extra arguments.
		if parameter == nil && takesRest {
			continue
		} // Missing rest items make an empty array.
		if parameter == nil {
			given = l.checker.GetUndefinedType()
			parameter = actual
		}
		if givenRest && !takesRest {
			given = l.checker.GetUnionType([]*checker.Type{given, l.checker.GetUndefinedType()})
		}
		if !l.censusRelated(given, takes) {
			name := func(node *ast.Node) string {
				if ast.IsIdentifier(node.Name()) {
					return node.Name().Text()
				}
				return fmt.Sprintf("%d", index+1)
			}
			return &Refused{Where: l.program.Where(parameter), What: label + " parameter " + name(parameter) + " cannot be served by implementation parameter " + name(actual), Fix: "make the implementation accept every value admitted by this overload, without mutable widening or bivariance"}
		}
	}
	promised := l.checker.GetReturnTypeOfSignature(l.checker.GetSignatureFromDeclaration(overload))
	produced := l.checker.GetReturnTypeOfSignature(l.checker.GetSignatureFromDeclaration(implementation))
	if !l.censusRelated(produced, promised) {
		if l.censusNullableOverloadResult(produced, promised) {
			return nil // Each resolved call proves the result or checks its presence.
		}
		return &Refused{Where: l.program.Where(overload), What: label + " result " + l.checker.TypeToString(promised) + " cannot be served by implementation result " + l.checker.TypeToString(produced), Fix: "make the implementation result covariant with every overload result"}
	}
	return nil
}

func (l *lowering) censusOverloadParameter(parameters []*ast.Node, index int) (*checker.Type, *ast.Node, bool, error) {
	if len(parameters) == 0 {
		return nil, nil, false, nil
	}
	parameter := parameters[min(index, len(parameters)-1)]
	rest := parameter.AsParameterDeclaration().DotDotDotToken != nil
	if index >= len(parameters) && !rest {
		return nil, nil, false, nil
	}
	proven := l.checker.GetTypeAtLocation(parameter)
	if ast.IsIdentifier(parameter.Name()) {
		proven = l.censusCallableParameterType(l.symbol(parameter.Name()))
	}
	proven = l.concrete(proven)
	if rest {
		if !l.checker.IsArrayType(proven) {
			return nil, parameter, true, l.notYet(parameter, "an overload rest other than an array")
		}
		proven = l.checker.GetElementTypeOfArrayType(proven)
	}
	return proven, parameter, rest, nil
}

// Calls use the resolved overload's result representation, even when the
// implementation proves a narrower result. A plain false must become a present
// boolean | undefined, and a scalar result must be boxed when the caller sees a union.
func (l *lowering) censusOverloadResult(call *ast.CallExpression, value ir.Expression) (ir.Expression, error) {
	symbol := l.symbol(ast.SkipParentheses(call.Expression))
	overloaded := false
	if symbol != nil {
		for _, declaration := range symbol.Declarations {
			if declaration.Kind == ast.KindFunctionDeclaration && declaration.Body() == nil && l.censusImplementation(declaration) != nil {
				overloaded = true
				break
			}
		}
	}
	if !overloaded {
		return value, nil
	}
	resolved := l.checker.GetResolvedSignature(call.AsNode())
	if resolved != nil && resolved.Declaration() != nil {
		overload := resolved.Declaration()
		implementation := l.censusImplementation(overload)
		if implementation != nil && overload.Body() == nil {
			if overload.Type() != nil && overload.Type().Kind == ast.KindTypePredicate {
				return l.predicateOverloadResult(call, value, implementation, overload)
			}
			ordinal := 0
			for _, declaration := range symbol.Declarations {
				if declaration.Kind == ast.KindFunctionDeclaration && declaration.Body() == nil {
					ordinal++
					if declaration == overload {
						break
					}
				}
			}
			if !l.censusProveOverloadResult(implementation, overload) {
				promised := l.checker.GetReturnTypeOfSignature(resolved)
				produced := l.checker.GetReturnTypeOfSignature(l.checker.GetSignatureFromDeclaration(implementation))
				if l.censusHasUndefined(produced) && !l.censusHasUndefined(promised) {
					of, err := l.typeOf(call.AsNode())
					if err != nil {
						return nil, err
					}
					message := fmt.Sprintf("overload %d of %s result: expected %s, got undefined", ordinal, implementation.Name().Text(), l.checker.TypeToString(promised))
					return ir.Coalesce{Value: value, Of: of, Panic: ir.StringConstant{Index: l.constant(message)}}, nil
				}
			}
		}
	}
	if value.Type() == 0 {
		return value, nil
	}
	of, err := l.typeOf(call.AsNode())
	if err != nil {
		return nil, err
	}
	value = fit(value, of)
	if value.Type() != of {
		return nil, l.notYet(call.AsNode(), "an overload result requiring another representation")
	}
	return value, nil
}

// Callable slots use the same tagged boolean representation as fields.
func censusCallableSlotless(of ir.Type) bool {
	return slotless(of) && of != ir.MaybeBoolean && of != ir.Union
}

// A default's body-local type excludes undefined, but its incoming argument can be undefined.
func (l *lowering) censusCallableParameter(parameter *ast.Symbol) (ir.Type, bool) {
	of, known := l.representation(l.checker.GetTypeOfSymbol(parameter))
	for _, declaration := range parameter.Declarations {
		if declaration.Kind == ast.KindParameter && declaration.AsParameterDeclaration().Initializer != nil {
			of = ir.Maybe(of)
		}
	}
	return of, known
}

// Signature symbols describe the body-local type of a defaulted parameter. The
// callable contract also accepts undefined, which selects that parameter's default.
func (l *lowering) censusCallableParameterType(parameter *ast.Symbol) *checker.Type {
	of := l.checker.GetTypeOfSymbol(parameter)
	for _, declaration := range parameter.Declarations {
		if declaration.Kind == ast.KindParameter && declaration.AsParameterDeclaration().Initializer != nil {
			return l.checker.GetUnionType([]*checker.Type{of, l.checker.GetUndefinedType()})
		}
	}
	return of
}

// Only exactly true is truthy in boolean | undefined. Equality evaluates the value once.
func censusBooleanCondition(value ir.Expression) ir.Expression {
	if value.Type() == ir.MaybeBoolean {
		return ir.Binary{Operator: ir.Equal, Left: value, Right: fit(ir.BooleanConstant{Value: true}, ir.MaybeBoolean)}
	}
	return value
}

func (l *lowering) censusBooleanLogical(node *ast.Node, operator ast.Kind, left, right ir.Expression) (ir.Expression, bool) {
	if operator != ast.KindAmpersandAmpersandToken && operator != ast.KindBarBarToken {
		return nil, false
	}
	boolean := func(of ir.Type) bool { return of == ir.Boolean || of == ir.MaybeBoolean }
	if !boolean(left.Type()) || !boolean(right.Type()) {
		return nil, false
	}
	of, err := l.typeOf(node)
	if err != nil || !boolean(of) {
		// Two booleans give a boolean whatever the checker narrowed the whole to: a branch it
		// knows is dead types the expression never, and that branch must still lower.
		if left.Type() != ir.Boolean || right.Type() != ir.Boolean {
			return nil, false
		}
		of = ir.Boolean
	}
	lowered := ir.And
	if operator == ast.KindBarBarToken {
		lowered = ir.Or
	}
	if lowered == ir.And && left.Type() == ir.MaybeBoolean {
		of = ir.MaybeBoolean
	}
	if of == ir.MaybeBoolean {
		left, right = fit(left, of), fit(right, of)
	} else {
		left, right = censusBooleanCondition(left), censusBooleanCondition(right)
	}
	return ir.Binary{Operator: lowered, Left: left, Right: right}, true
}

// ToBoolean never calls user conversion methods. Every represented value can be tested.
// NumberCall already carries a single evaluated argument through both backends and analyses.
func censusCondition(value ir.Expression) ir.Expression {
	if value.Type() == ir.Boolean {
		return value
	}
	return ir.NumberCall{Function: "toBoolean", Arguments: []ir.Expression{value}}
}

// A never-rest signature is an erased callable marker. No ordinary argument can
// inhabit its rest element; storage compares results without pairing parameters.
func (l *lowering) censusNeverRestSignature(signature *checker.Signature) bool {
	parameters := signature.Parameters()
	if len(parameters) != 1 {
		return false
	}
	rest := false
	for _, declaration := range parameters[0].Declarations {
		if declaration.Kind == ast.KindParameter && declaration.AsParameterDeclaration().DotDotDotToken != nil {
			rest = true
		}
	}
	if !rest {
		return false
	}
	parameter := l.concrete(l.checker.GetTypeOfSymbol(parameters[0]))
	if l.checker.IsArrayType(parameter) {
		parameter = l.checker.GetElementTypeOfArrayType(parameter)
	}
	return parameter.Flags()&checker.TypeFlagsNever != 0
}

internal/lower/expression.go:
package lower

import (
	"errors"
	"reflect"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
)

// typeOf is what's left at runtime of the type the checker proved for a node: a number, a boolean or
// a string. A union counts when every member is the same one ('Fizz' | 'Buzz' is a string).
func (l *lowering) typeOf(node *ast.Node) (ir.Type, error) {
	if l.enumNeverIdentity(node, map[*ast.Node]bool{}) != nil {
		if symbol := l.flagValueSymbol(ast.SkipParentheses(node)); symbol != nil {
			if stored, known := l.representation(l.checker.GetTypeOfSymbol(symbol)); known {
				return stored, nil
			}
		}
		return ir.Number, nil
	}
	if ast.IsIdentifier(node) && l.exactPlainObject(node) {
		return ir.Object, nil
	}
	if node.Kind == ast.KindPropertyAccessExpression && l.checker.GetTypeAtLocation(node).Flags()&checker.TypeFlagsUndefined != 0 {
		// A field narrowed to undefined still occupies its declared slot, which may hold a packed
		// optional number or a different reference kind. Read that representation, not an object.
		if field := l.checker.GetSymbolAtLocation(node.Name()); field != nil {
			return l.typeOfSymbol(node, field)
		}
	}
	if l.checker.GetTypeAtLocation(node).Flags()&checker.TypeFlagsUndefined != 0 && (node.Kind == ast.KindVoidExpression || voidInitializer(node)) {
		return ir.Object, nil
	}
	if valueType, isKnown := l.representation(l.arrayPredicateObservedType(node)); isKnown {
		return valueType, nil
	}
	return 0, l.notYet(node, "a value of type "+l.checker.TypeToString(l.checker.GetTypeAtLocation(node)))
}

func (l *lowering) representation(proven *checker.Type) (ir.Type, bool) {
	proven = l.concrete(proven)
	if kind := l.typedArrayKind(proven); kind != 0 {
		return kind, true
	}
	flags := proven.Flags()
	if flags&(checker.TypeFlagsUnknown|checker.TypeFlagsNonPrimitive) != 0 {
		return ir.Union, true
	}
	if flags&checker.TypeFlagsIntersection != 0 {
		for _, part := range proven.Types() {
			if part.Flags()&checker.TypeFlagsNonPrimitive != 0 {
				return ir.Union, true
			}
		}
	}
	if l.nodeBufferType(proven, "Buffer") {
		return ir.Array, true
	}
	if flags&checker.TypeFlagsTypeParameter != 0 {
		// Inside a generic class, a type parameter is what this instantiation made it.
		substituted, isKnown := l.substitution[proven]
		return substituted, isKnown
	}
	if flags&checker.TypeFlagsIntersection != 0 {
		// Target & WeakBrand is what a Weak<Target> reads as where it's present: the target.
		if target := l.weakTarget(proven); target != nil {
			return l.representation(target)
		}
		return l.objectIntersection(proven)
	}
	switch {
	case flags&(checker.TypeFlagsNull|checker.TypeFlagsUndefined|checker.TypeFlagsVoid) != 0:
		return ir.Object, true
	case flags&checker.TypeFlagsNumberLike != 0:
		return ir.Number, true
	case flags&checker.TypeFlagsStringLike != 0:
		return ir.String, true
	case flags&checker.TypeFlagsBooleanLike != 0:
		return ir.Boolean, true
	case flags&checker.TypeFlagsObject != 0 && (l.checker.IsArrayType(proven) || l.isLibraryType(proven, "RegExpExecArray", "RegExpMatchArray", "RegExpIndicesArray")):
		return ir.Array, true
	case flags&checker.TypeFlagsObject != 0 && l.isLibraryType(proven, "Map", "ReadonlyMap", "Set", "ReadonlySet"):
		// A Set is held as a Map whose values aren't used (set.go).
		return ir.Map, true
	case flags&checker.TypeFlagsObject != 0 && !isClassInstance(proven) && (l.checker.IsTypeAssignableTo(l.checker.GetNumberType(), proven) || l.checker.IsTypeAssignableTo(l.checker.GetStringType(), proven) || l.checker.IsTypeAssignableTo(l.checker.GetBooleanType(), proven)):
		// Structural types such as {} admit primitives. Their slots must preserve
		// the runtime brand with the same boxes used for scalar/reference unions.
		return ir.Union, true
	case flags&checker.TypeFlagsObject != 0 && len(l.checker.GetSignaturesOfType(proven, checker.SignatureKindCall)) == 0:
		return ir.Object, true
	case flags&checker.TypeFlagsObject != 0:
		// An object with call signatures is a function, held as a closure.
		return ir.Closure, true
	case flags&checker.TypeFlagsUnion != 0:
		if l.includesNull(proven) && !dynamicObjectType(proven) {
			// Preserve the area's nullable reference and RegExp protocols. Only
			// differently stored members need the boxed union representation.
			boxed := l.includesUndefined(proven)
			for _, member := range proven.Types() {
				if member.Flags()&(checker.TypeFlagsNull|checker.TypeFlagsUndefined) != 0 {
					continue
				}
				of, known := l.representation(member)
				if !known {
					return 0, false
				}
				boxed = boxed || !of.IsReference() || of == ir.String || of == ir.Union
			}
			if boxed {
				return ir.Union, true
			}
		}
		var shared ir.Type
		mixed, weak := false, false
		for _, member := range proven.Types() {
			if member.Flags()&(checker.TypeFlagsUndefined|checker.TypeFlagsNull) != 0 {
				// undefined joins a union of references as a null pointer; it's checked below that
				// the rest are references.
				continue
			}
			if l.weakTarget(member) != nil {
				// Weak<Target> is (Target & WeakBrand) | undefined: kept weakly.
				weak = true
				continue
			}
			memberType, isKnown := l.representation(member)
			if !isKnown {
				return 0, false
			}
			if shared != 0 && memberType != shared {
				mixed = true
			}
			shared = memberType
		}
		if weak {
			return ir.Weak, shared == 0
		}
		if mixed {
			// Members held differently (string | number) are one Union, which holds undefined too.
			return ir.Union, true
		}
		if shared != 0 && !shared.IsReference() && l.includesUndefined(proven) {
			// number | undefined and boolean | undefined are each a present-and-value pair.
			if maybe := ir.Maybe(shared); maybe.IsMaybe() {
				return maybe, true
			}
			return 0, false
		}
		return shared, shared != 0
	}
	return 0, false
}

// isLibraryType reports whether a type is one of the library's, by name: Map, not a program's own
// interface that happens to be called Map.
func (l *lowering) isLibraryType(proven *checker.Type, names ...string) bool {
	symbol := proven.Symbol()
	if symbol == nil || len(symbol.Declarations) == 0 || !load.IsLibrary(ast.GetSourceFileOfNode(symbol.Declarations[0])) {
		return false
	}
	for _, name := range names {
		if symbol.Name == name {
			return true
		}
	}
	return false
}

func (l *lowering) includesUndefined(proven *checker.Type) bool {
	if proven.Flags()&checker.TypeFlagsUnion == 0 {
		return proven.Flags()&checker.TypeFlagsUndefined != 0
	}
	for _, member := range proven.Types() {
		if member.Flags()&checker.TypeFlagsUndefined != 0 {
			return true
		}
	}
	return false
}

func (l *lowering) includesNull(proven *checker.Type) bool {
	if proven.Flags()&checker.TypeFlagsUnion == 0 {
		return proven.Flags()&checker.TypeFlagsNull != 0
	}
	for _, member := range proven.Types() {
		if l.includesNull(member) {
			return true
		}
	}
	return false
}

// expression lowers a value. What's kept weakly (a Weak<Target> variable, field, element or map value)
// is read here as its target, so no value of a Weak type goes further; keeping one is fit's WeakOf.
func (l *lowering) expression(node *ast.Node) (ir.Expression, error) {
	if err := l.libraryIteratorUnsupportedUse(node); err != nil {
		return nil, err
	}
	if err := l.nodeBufferUnsupportedUse(node); err != nil {
		return nil, err
	}
	if err := l.regexUnsupportedUse(node); err != nil {
		return nil, err
	}
	value, err := l.value(node)
	if err == nil {
		if contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone); contextual != nil {
			if err := l.unknownView(node, l.checker.GetTypeAtLocation(node), contextual); err != nil {
				return nil, err
			}
		}
	}
	if err == nil && value.Type() != ir.Weak && l.checker.GetTypeAtLocation(node).Flags()&checker.TypeFlagsUndefined != 0 {
		if _, constant := value.(ir.Undefined); !constant {
			if contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone); contextual != nil {
				if to, known := l.representation(contextual); known && to != value.Type() && to != ir.Union && (to.IsMaybe() || to.IsReference()) {
					// Keep the read or call's effects when converting its only possible value.
					value = ir.Narrow{Value: ir.Box{Value: value}, To: to}
				}
			}
		}
	}
	if literal := ast.SkipParentheses(node).Kind; err == nil && value.Type().IsReference() && literal != ast.KindArrayLiteralExpression && literal != ast.KindObjectLiteralExpression {
		// The checker lets { v: Box } be seen as { v: Weak<Box> } and back, an array of Box as one of
		// Weak<Box>, and (x: Weak<Box>) => ... as (x: Box) => ...; but one keeps a handle where the
		// other keeps the target, so the same object, array or function can't be both. A tuple is held
		// as an object, so it can't be seen as an array either, here or anywhere inside. A literal is
		// made as the type it's written into, so it never differs.
		if contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone); contextual != nil {
			if own := l.checker.GetTypeAtLocation(node); !l.nodeBufferView(l.present(own), l.present(contextual)) && !l.nodeBufferReadArgument(node) && !l.nodeFSFileBufferArgument(node) {
				return nil, l.notYet(node, "Buffer or Hash viewed as another object type (native host internal slots)")
			}
			if own := l.checker.GetTypeAtLocation(node); !l.typedArraySetArgument(node) && !l.nodeBufferReadArgument(node) && !l.nodeFSFileBufferArgument(node) && !l.sameKeeping(own, contextual, map[[2]*checker.Type]bool{}) {
				if l.typedArrayKind(l.checker.GetNonNullableType(own)) != 0 {
					return nil, l.notYet(node, "a typed array seen through a structural view that loses its buffer representation")
				}
				return nil, l.notYet(node, "a "+l.checker.TypeToString(own)+" seen as a "+l.checker.TypeToString(contextual)+" (one keeps something weakly that the other keeps strongly)")
			} else if tuple, array := l.tupleSeenAsArray(own, contextual, map[[2]*checker.Type]bool{}); tuple != nil {
				return nil, l.notYet(node, "a "+l.checker.TypeToString(tuple)+" seen as a "+l.checker.TypeToString(array)+" (a tuple is held as an object, not an array, so far; write it as an array where it's made, or copy it into one: [pair[0], pair[1]])")
			}
		}
	}
	// Anything the check above doesn't see (a tuple inside a literal, or a union around it) is still
	// not yet: wherever a tuple flows into an array slot, at any depth.
	if skipped := ast.SkipParentheses(node); err == nil && skipped.Kind != ast.KindSpreadElement {
		if contextual := l.checker.GetContextualType(skipped, checker.ContextFlagsNone); contextual != nil && l.tupleWhereArrayGoes(l.checker.GetTypeAtLocation(skipped), contextual, 0) {
			return nil, l.notYet(skipped, "a tuple where an array goes (as "+l.checker.TypeToString(contextual)+")")
		}
	}
	if err != nil || value.Type() != ir.Weak {
		return value, err
	}
	read := l.checker.GetTypeAtLocation(node)
	to, present := ir.Object, false
	if target, isKnown := l.representation(read); isKnown && target != ir.Weak && read.Flags()&checker.TypeFlagsUndefined == 0 {
		// The checker narrowed it to present (Target & WeakBrand).
		to, present = target, true
	} else if read.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range read.Types() {
			if target := l.weakTarget(member); target != nil {
				if to, isKnown = l.representation(target); !isKnown {
					return nil, l.notYet(node, "a Weak of "+l.checker.TypeToString(target))
				}
			}
		}
	}
	if !to.IsReference() {
		return nil, l.notYet(node, "a Weak of "+l.checker.TypeToString(read))
	}
	return ir.WeakTarget{Value: value, To: to, Present: present}, nil
}

// sameKeeping reports whether a value of type from, seen as type to, keeps everything inside it the
// same way through both: every field to has, every element, map key and value, and every parameter
// and result of a function, Weak in both or in neither, all the way down.
func (l *lowering) sameKeeping(from *checker.Type, to *checker.Type, visited map[[2]*checker.Type]bool) bool {
	from, to = l.present(from), l.present(to)
	if from == nil || to == nil || from == to || visited[[2]*checker.Type{from, to}] {
		return true
	}
	visited[[2]*checker.Type{from, to}] = true
	if fromKind, toKind := l.typedArrayKind(from), l.typedArrayKind(to); fromKind != 0 || toKind != 0 {
		return fromKind != 0 && fromKind == toKind
	}
	if !l.nodeBufferView(from, to) {
		return false
	}
	same := func(inside, viewed *checker.Type) bool {
		fromKept, _ := l.kept(inside)
		toKept, _ := l.kept(viewed)
		return (fromKept == ir.Weak) == (toKept == ir.Weak) && l.sameKeeping(inside, viewed, visited)
	}
	fromSignatures := l.checker.GetSignaturesOfType(from, checker.SignatureKindCall)
	toSignatures := l.checker.GetSignaturesOfType(to, checker.SignatureKindCall)
	switch {
	case len(fromSignatures) > 0 && len(toSignatures) > 0:
		// A closure's slots have no dynamic type descriptor. A view changing a boxed union
		// to an unboxed scalar (or back) needs an adapter. References share the union pointer ABI.
		sameCallable := func(inside, viewed *checker.Type) bool {
			fromKept, _ := l.kept(inside)
			toKept, _ := l.kept(viewed)
			return !(fromKept == ir.Union && !toKept.IsReference() || toKept == ir.Union && !fromKept.IsReference()) && same(inside, viewed)
		}
		// Intrinsic callback adapters call the source signature, not the library's wider view.
		if declaration := toSignatures[0].Declaration(); declaration != nil && load.IsLibrary(ast.GetSourceFileOfNode(declaration)) {
			sameCallable = same
		}
		fromParameters, toParameters := fromSignatures[0].Parameters(), toSignatures[0].Parameters()
		if l.censusNeverRestSignature(toSignatures[0]) {
			toParameters = nil
		}
		for index := 0; index < len(fromParameters) && index < len(toParameters); index++ {
			if !sameCallable(l.checker.GetTypeOfSymbol(fromParameters[index]), l.checker.GetTypeOfSymbol(toParameters[index])) {
				return false
			}
		}
		return sameCallable(l.checker.GetReturnTypeOfSignature(fromSignatures[0]), l.checker.GetReturnTypeOfSignature(toSignatures[0]))
	case from.ObjectFlags()&checker.ObjectFlagsReference != 0 && to.ObjectFlags()&checker.ObjectFlagsReference != 0 && (l.checker.IsArrayType(from) || checker.IsTupleType(from) || l.isLibraryType(from, "Map", "ReadonlyMap", "Set", "ReadonlySet")):
		fromArguments, toArguments := l.typeArguments(from), l.typeArguments(to)
		for index := 0; index < len(fromArguments) && index < len(toArguments); index++ {
			if !same(fromArguments[index], toArguments[index]) {
				return false
			}
		}
	default:
		for _, viewed := range l.checker.GetPropertiesOfType(to) {
			if viewed.Flags&ast.SymbolFlagsMethod != 0 {
				continue
			}
			if inside := l.checker.GetPropertyOfType(from, viewed.Name); inside != nil && !same(l.checker.GetTypeOfSymbol(inside), l.checker.GetTypeOfSymbol(viewed)) {
				return false
			}
		}
	}
	return true
}

// tupleSeenAsArray finds, in a value of type from seen as type to, the first tuple seen as an array:
// at the top, or as an element, field, map key or value, parameter or result, all the way down as
// sameKeeping walks. It returns the tuple's type and the array's, or nils.
func (l *lowering) tupleSeenAsArray(from *checker.Type, to *checker.Type, visited map[[2]*checker.Type]bool) (*checker.Type, *checker.Type) {
	from, to = l.present(from), l.present(to)
	if from == nil || to == nil || from == to || visited[[2]*checker.Type{from, to}] {
		return nil, nil
	}
	visited[[2]*checker.Type{from, to}] = true
	if checker.IsTupleType(from) && !checker.IsTupleType(to) {
		return from, to
	}
	fromSignatures := l.checker.GetSignaturesOfType(from, checker.SignatureKindCall)
	toSignatures := l.checker.GetSignaturesOfType(to, checker.SignatureKindCall)
	switch {
	case len(fromSignatures) > 0 && len(toSignatures) > 0:
		// A function is handed the other's arguments, and its results are seen as the other's.
		fromParameters, toParameters := fromSignatures[0].Parameters(), toSignatures[0].Parameters()
		if l.censusNeverRestSignature(toSignatures[0]) {
			toParameters = nil
		}
		for index := 0; index < len(fromParameters) && index < len(toParameters); index++ {
			if tuple, array := l.tupleSeenAsArray(l.checker.GetTypeOfSymbol(toParameters[index]), l.checker.GetTypeOfSymbol(fromParameters[index]), visited); tuple != nil {
				return tuple, array
			}
		}
		return l.tupleSeenAsArray(l.checker.GetReturnTypeOfSignature(fromSignatures[0]), l.checker.GetReturnTypeOfSignature(toSignatures[0]), visited)
	case from.ObjectFlags()&checker.ObjectFlagsReference != 0 && to.ObjectFlags()&checker.ObjectFlagsReference != 0 && (l.checker.IsArrayType(from) || checker.IsTupleType(from) || l.isLibraryType(from, "Map", "ReadonlyMap", "Set", "ReadonlySet")):
		fromArguments, toArguments := l.typeArguments(from), l.typeArguments(to)
		if checker.IsTupleType(from) && l.checker.IsArrayType(to) {
			return from, to
		}
		for index := 0; index < len(fromArguments) && index < len(toArguments); index++ {
			if tuple, array := l.tupleSeenAsArray(fromArguments[index], toArguments[index], visited); tuple != nil {
				return tuple, array
			}
		}
	default:
		for _, viewed := range l.checker.GetPropertiesOfType(to) {
			if viewed.Flags&ast.SymbolFlagsMethod != 0 {
				continue
			}
			if inside := l.checker.GetPropertyOfType(from, viewed.Name); inside != nil {
				if tuple, array := l.tupleSeenAsArray(l.checker.GetTypeOfSymbol(inside), l.checker.GetTypeOfSymbol(viewed), visited); tuple != nil {
					return tuple, array
				}
			}
		}
	}
	return nil, nil
}

// present is a type without undefined, and a Weak's narrowing without its brand: the one object,
// array, map or function type it is, or nil when it's none or several.
func (l *lowering) present(proven *checker.Type) *checker.Type {
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		var only *checker.Type
		for _, member := range proven.Types() {
			if member.Flags()&(checker.TypeFlagsUndefined|checker.TypeFlagsNull) != 0 {
				continue
			}
			if only != nil {
				return nil
			}
			only = member
		}
		if only == nil {
			return nil
		}
		proven = only
	}
	if target := l.weakTarget(proven); target != nil {
		proven = target
	}
	if proven.Flags()&checker.TypeFlagsObject == 0 {
		return nil
	}
	return proven
}

// kept is how an element or a map's value of a type is kept: as its representation, except that one
// narrowed from a Weak (Node & WeakBrand, as filter(x => x !== undefined) or every leaves an array of
// Weak<Node>) is still a Weak, a handle, since that's what the array holds.
func (l *lowering) kept(proven *checker.Type) (ir.Type, bool) {
	if l.weakTarget(proven) != nil {
		return ir.Weak, true
	}
	return l.representation(proven)
}

// typeArguments is a generic type's arguments, Map<K, V>'s K and V, through a Weak's narrowing
// (Map<K, V> & WeakBrand), or nil for a type that has none.
func (l *lowering) typeArguments(proven *checker.Type) []*checker.Type {
	if target := l.weakTarget(proven); target != nil {
		proven = target
	}
	if proven.Flags()&checker.TypeFlagsObject == 0 || proven.ObjectFlags()&checker.ObjectFlagsReference == 0 {
		return nil
	}
	return l.checker.GetTypeArguments(proven)
}

// weakTarget is the Target of Target & WeakBrand, the present half of a Weak<Target>, or nil for
// any other type.
func (l *lowering) weakTarget(proven *checker.Type) *checker.Type {
	if proven.Flags()&checker.TypeFlagsIntersection == 0 {
		return nil
	}
	var target *checker.Type
	branded := false
	for _, member := range proven.Types() {
		if symbol := member.Symbol(); symbol != nil && symbol.Name == "WeakBrand" && len(symbol.Declarations) > 0 && load.IsPrelude(ast.GetSourceFileOfNode(symbol.Declarations[0])) {
			branded = true
		} else if target == nil {
			target = member
		} else {
			return nil
		}
	}
	if !branded {
		return nil
	}
	return target
}

// value lowers a value, as expression does, but leaves a Weak as it's kept.
func (l *lowering) value(node *ast.Node) (ir.Expression, error) {
	if identity := l.enumNeverIdentity(node, map[*ast.Node]bool{}); identity != nil {
		value, err := l.enumNeverValue(node)
		if err != nil {
			return nil, err
		}
		return l.enumNeverCheck(node, value, identity), nil
	}
	return l.enumNeverValue(node)
}

func (l *lowering) enumNeverValue(node *ast.Node) (ir.Expression, error) {
	node = ast.SkipParentheses(node)
	if value, handled, err := l.typedArrayExpression(node); handled {
		return value, err
	}
	if value, known, err := l.namespaceExpression(node); known {
		return value, err
	}
	if value, known, err := l.libraryMethodValue(node); known {
		return value, err
	}
	if l.isArgumentsLength(node) {
		return l.readArgumentsCount(), nil
	}
	if value, known, err := l.enumExpression(node); known {
		return value, err
	}
	if observed, known := l.libraryArrayObservation(node); known {
		return observed, nil
	}
	switch node.Kind {
	case ast.KindNullKeyword:
		return ir.Null{}, nil
	case ast.KindRegularExpressionLiteral:
		return l.regexConstant(node)
	case ast.KindNumericLiteral:
		return l.numericLiteral(node)
	case ast.KindStringLiteral, ast.KindNoSubstitutionTemplateLiteral:
		return ir.StringConstant{Index: l.constant(node.Text())}, nil
	case ast.KindTrueKeyword, ast.KindFalseKeyword:
		return ir.BooleanConstant{Value: node.Kind == ast.KindTrueKeyword}, nil
	case ast.KindIdentifier:
		if value, known, err := l.libraryGlobalValue(node); known {
			return value, err
		}
		if value, handled := l.staticClassRead(node); handled {
			return value, nil
		}
		if value, handled, err := l.nestedReference(node); handled {
			return value, err
		}
		local, isLocal := l.local(node)
		if !isLocal && node.Text() == "undefined" {
			return ir.Undefined{}, nil
		}
		if !isLocal && (l.isLibraryGlobal(node, "NaN") || l.isLibraryGlobal(node, "Infinity")) {
			return ir.NumberConstant{Value: numberConstants[node.Text()]}, nil
		}
		if function, isFunction := l.functions[l.symbol(node)]; !isLocal && isFunction {
			return l.functionValue(node, function)
		}
		if _, isGeneric := l.generics[l.symbol(node)]; !isLocal && isGeneric {
			return nil, l.notYet(node, "a generic function as a value")
		}
		if !isLocal && l.isLibraryGlobal(node, "String") {
			return nil, l.notYet(node, "reading String as a first-class constructor (its any-typed call signature, construction and static members need an intrinsic value representation)")
		}
		if !isLocal {
			return nil, l.notYet(node, "reading "+node.Text())
		}
		return l.localRead(node, local)
	case ast.KindVoidExpression:
		operand, err := l.discardedValue(node.AsVoidExpression().Expression)
		if err != nil {
			return nil, err
		}
		return ir.Void{Value: operand}, nil
	case ast.KindPrefixUnaryExpression:
		return l.prefix(node)
	case ast.KindTypeOfExpression:
		if l.isLibraryGlobal(node.AsTypeOfExpression().Expression, "Number") {
			return ir.StringConstant{Index: l.constant("function")}, nil
		}
		if value, intrinsic := l.stringTypeOf(node); intrinsic {
			return value, nil
		}
		operand, err := l.expression(node.AsTypeOfExpression().Expression)
		if err != nil {
			return nil, err
		}
		written := node.AsTypeOfExpression().Expression
		null := l.typeOfNull(written)
		if null && l.includesUndefined(l.concrete(l.checker.GetTypeAtLocation(written))) {
			switch operand.(type) {
			case ir.ArrayIndex, ir.MapGet, ir.ArrayPop:
				// The lookup still has a presence slot, so typeof can distinguish null from undefined.
			default:
				return nil, l.notYet(node, "typeof a value holding both null and undefined without a presence slot")
			}
		}
		return ir.TypeOf{Value: operand, Null: null}, nil
	case ast.KindBinaryExpression:
		binary := node.AsBinaryExpression()
		if _, compound := compoundAssignments[binary.OperatorToken.Kind]; compound || binary.OperatorToken.Kind == ast.KindEqualsToken {
			return l.assignmentValue(node)
		}
		if binary.OperatorToken.Kind == ast.KindCommaToken {
			return l.comma(node)
		}
		if logicalAssignment(binary.OperatorToken.Kind) {
			return l.logicalAssignment(node)
		}
		if binary.OperatorToken.Kind == ast.KindInKeyword {
			return l.inProperty(node)
		}
		if binary.OperatorToken.Kind == ast.KindQuestionQuestionToken {
			return l.coalesce(node)
		}
		if binary.OperatorToken.Kind == ast.KindInstanceOfKeyword {
			if lowered, isCaught := l.caughtInstanceOfError(node); isCaught {
				return lowered, nil
			}
			return l.classInstanceOf(node)
		}
		// A flow-narrowed never expression still reads its declared boolean slots.
		// Only a live result needs a placeholder for a non-returning arm.
		if (binary.OperatorToken.Kind == ast.KindBarBarToken || binary.OperatorToken.Kind == ast.KindAmpersandAmpersandToken) && l.isNever(binary.Right) && !l.isNever(node) {
			return l.logicalNever(node)
		}
		left, err := l.expression(binary.Left)
		if err != nil {
			return nil, err
		}
		right, err := l.expression(binary.Right)
		if err != nil {
			return nil, err
		}
		if binary.OperatorToken.Kind == ast.KindPlusToken {
			left, right = l.spelled(binary.Left, left), l.spelled(binary.Right, right)
		}
		return l.combine(node, binary.OperatorToken.Kind, left, right)
	case ast.KindTaggedTemplateExpression:
		return l.stringRawTemplate(node)
	case ast.KindTemplateExpression:
		return l.template(node)
	case ast.KindConditionalExpression:
		return l.conditional(node)
	case ast.KindObjectLiteralExpression:
		return l.objectLiteral(node)
	case ast.KindArrayLiteralExpression:
		return l.arrayLiteral(node)
	case ast.KindPropertyAccessExpression:
		return l.property(node)
	case ast.KindElementAccessExpression:
		return l.elementAccess(node)
	case ast.KindNewExpression:
		return l.newExpression(node)
	case ast.KindThisKeyword:
		if l.this < 0 {
			return nil, l.notYet(node, "this outside a method")
		}
		if err := l.useOfThis(node); err != nil {
			return nil, err
		}
		l.touch(l.this)
		return ir.Read{Local: l.this, Of: ir.Object}, nil
	case ast.KindArrowFunction:
		return l.closure(node)
	case ast.KindNonNullExpression:
		return l.nonNull(node)
	case ast.KindAsExpression:
		return l.cast(node)
	case ast.KindSatisfiesExpression:
		satisfies := node.AsSatisfiesExpression()
		if err := l.provenRelation(node, satisfies.Expression, l.checker.GetTypeAtLocation(satisfies.Type)); err != nil {
			return nil, err
		}
		return l.expression(satisfies.Expression)
	case ast.KindFunctionExpression:
		return l.functionExpression(node)
	case ast.KindCallExpression:
		if value, known, err := l.optionalIntrinsic(node); known {
			return value, err
		}
		if err := l.optionalCall(node); err != nil {
			return nil, err
		}
		if lowered, isBuiltin, err := l.builtin(node); isBuiltin {
			if err == nil && lowered.Type() == 0 {
				return ir.Effects{Body: []ir.Statement{ir.Evaluate{Value: lowered}}, Result: ir.Undefined{}}, nil
			}
			return lowered, err
		}
		call, err := l.callOrMethod(node)
		if err != nil {
			return nil, err
		}
		if call.Type() == 0 {
			return ir.Effects{Body: []ir.Statement{ir.Evaluate{Value: call}}, Result: ir.Undefined{}}, nil
		}
		return call, nil
	}
	return nil, l.notYet(node, describe(node))
}

// fit makes a value fit where a value of type to goes: a number or a boolean, or undefined, where
// number | undefined or boolean | undefined goes, since that is two words and they are one. It also
// unwraps a maybe value the checker narrowed to its present type. Anything else is left as it is.
func fit(value ir.Expression, to ir.Type) ir.Expression {
	if discarded, ok := value.(ir.Void); ok && (to.IsMaybe() || to.IsReference()) {
		discarded.Of = to
		return discarded
	}
	if to == ir.Weak && value != nil && value.Type() != ir.Weak {
		return ir.WeakOf{Value: value}
	}
	if to == ir.Union && value != nil && value.Type() != ir.Union {
		return ir.Box{Value: value}
	}
	if _, isNull := value.(ir.Null); isNull && to.IsReference() && to != ir.Union {
		return ir.Null{Of: to}
	}
	if _, isUndefined := value.(ir.Undefined); isUndefined && to.IsReference() && to != ir.Union {
		// undefined going where a string, an array or a function may be missing is that reference,
		// missing: typed as it, so the C holding it is.
		return ir.Undefined{Of: to}
	}
	if !to.IsMaybe() || value == nil {
		if value != nil && value.Type().IsMaybe() && value.Type().Present() == to {
			return ir.Unwrap{Value: value}
		}
		return value
	}
	if value.Type() == to.Present() {
		return ir.MaybeOf{Value: value, Of: to}
	}
	if _, isUndefined := value.(ir.Undefined); isUndefined {
		return ir.MaybeOf{Of: to}
	}
	return value
}

// numericLiteral is the value the checker read from the literal, so 0x1F, 1_000 and 1e3 all mean
// what JavaScript says they mean without a second parser here.
func (l *lowering) numericLiteral(node *ast.Node) (ir.Expression, error) {
	literal := l.checker.GetTypeAtLocation(node)
	if literal.Flags()&checker.TypeFlagsNumberLiteral == 0 {
		return nil, errors.New("lower: " + l.program.Where(node) + ": the checker gave a numeric literal a type that isn't a number literal")
	}
	value := reflect.ValueOf(literal.AsLiteralType().Value())
	if value.Kind() != reflect.Float64 {
		return nil, errors.New("lower: " + l.program.Where(node) + ": a numeric literal's value isn't a float64")
	}
	return ir.NumberConstant{Value: value.Float()}, nil
}

func (l *lowering) prefix(node *ast.Node) (ir.Expression, error) {
	prefix := node.AsPrefixUnaryExpression()
	if prefix.Operator == ast.KindPlusPlusToken || prefix.Operator == ast.KindMinusMinusToken {
		operand := ast.SkipParentheses(prefix.Operand)
		if !ast.IsIdentifier(operand) {
			return nil, l.notYet(node, "a prefix update value whose target is not a plain name")
		}
		local, known := l.local(operand)
		if !known || l.result.Locals[local].Type != ir.Number {
			return nil, l.notYet(node, "a prefix update value whose name is not stored as a number")
		}
		// An immediately called helper makes the write and resulting read one expression.
		// Capturing a local carries its existing cell, so the caller observes the write.
		index := len(l.result.Functions)
		l.result.Functions = append(l.result.Functions, ir.Function{Name: "prefix_update", Closure: true, Returns: ir.Number})
		outerIndex := l.functionIndex
		l.functionIndex = index
		l.closures = append(l.closures, index)
		body, err := l.increment(node)
		var value ir.Expression
		if err == nil {
			value, err = l.expression(operand)
		}
		l.closures = l.closures[:len(l.closures)-1]
		l.functionIndex = outerIndex
		if err != nil {
			return nil, err
		}
		if value.Type() != ir.Number {
			return nil, l.notYet(node, "a prefix update of a non-number")
		}
		l.result.Functions[index].Body = append(body, ir.Return{Value: value})
		return ir.CallClosure{Closure: ir.MakeClosure{Function: index}, Returns: ir.Number}, nil
	}
	if prefix.Operator == ast.KindPlusToken || prefix.Operator == ast.KindMinusToken || prefix.Operator == ast.KindTildeToken {
		operand, err := l.libraryNumber(prefix.Operand)
		if err != nil {
			return nil, err
		}
		operator := ir.Plus
		if prefix.Operator == ast.KindMinusToken {
			operator = ir.Negate
		}
		if prefix.Operator == ast.KindTildeToken {
			operator = ir.BitNot
		}
		return ir.Unary{Operator: operator, Operand: operand}, nil
	}
	operand, err := l.expression(prefix.Operand)
	if err != nil {
		return nil, err
	}
	if prefix.Operator == ast.KindExclamationToken {
		return ir.Unary{Operator: ir.Not, Operand: censusCondition(operand)}, nil
	}
	return nil, l.notYet(node, describe(node)+" on a "+typeName(operand.Type()))
}

var arithmetic = map[ast.Kind]ir.Operator{
	ast.KindPlusToken:             ir.Add,
	ast.KindMinusToken:            ir.Subtract,
	ast.KindAsteriskToken:         ir.Multiply,
	ast.KindSlashToken:            ir.Divide,
	ast.KindPercentToken:          ir.Remainder,
	ast.KindAsteriskAsteriskToken: ir.Power,
}

// bitwise are the binary bitwise operators, on two numbers.
var bitwise = map[ast.Kind]ir.Operator{
	ast.KindAmpersandToken:                         ir.BitAnd,
	ast.KindBarToken:                               ir.BitOr,
	ast.KindCaretToken:                             ir.BitXor,
	ast.KindLessThanLessThanToken:                  ir.ShiftLeft,
	ast.KindGreaterThanGreaterThanToken:            ir.ShiftRight,
	ast.KindGreaterThanGreaterThanGreaterThanToken: ir.ShiftRightUnsigned,
}

var comparisons = map[ast.Kind]ir.Operator{
	ast.KindLessThanToken:          ir.Less,
	ast.KindLessThanEqualsToken:    ir.LessOrEqual,
	ast.KindGreaterThanToken:       ir.Greater,
	ast.KindGreaterThanEqualsToken: ir.GreaterOrEqual,
}

// combine lowers a binary operator on two lowered operands.
func (l *lowering) combine(node *ast.Node, operator ast.Kind, left ir.Expression, right ir.Expression) (ir.Expression, error) {
	both := func(want ir.Type) bool { return left.Type() == want && right.Type() == want }
	if operator == ast.KindPlusToken && (left.Type() == ir.String || right.Type() == ir.String) {
		spell := func(value ir.Expression) ir.Expression {
			switch value.Type() {
			case ir.Number:
				return ir.NumberToString{Value: value}
			case ir.Boolean:
				return ir.BooleanToString{Value: value}
			}
			return value
		}
		left, right = spell(left), spell(right)
	}
	if operator == ast.KindPlusToken && both(ir.String) {
		return ir.Concat{Parts: []ir.Expression{left, right}}, nil
	}
	if lowered, isArithmetic := arithmetic[operator]; isArithmetic && both(ir.Number) {
		return ir.Binary{Operator: lowered, Left: left, Right: right}, nil
	}
	if lowered, isBitwise := bitwise[operator]; isBitwise && both(ir.Number) {
		return ir.Binary{Operator: lowered, Left: left, Right: right}, nil
	}
	if lowered, isComparison := comparisons[operator]; isComparison && (both(ir.Number) || both(ir.String)) {
		// Strings compare in UTF-16 code unit order, as JavaScript's do.
		return ir.Binary{Operator: lowered, Left: left, Right: right}, nil
	}
	if operator == ast.KindEqualsEqualsEqualsToken || operator == ast.KindExclamationEqualsEqualsToken {
		_, leftNull := left.(ir.Null)
		_, rightNull := right.(ir.Null)
		if leftNull != rightNull {
			value := left
			if leftNull {
				value = right
			}
			if !value.Type().IsReference() {
				return nil, l.notYet(node, "null comparison with a scalar")
			}
			operand := node.AsBinaryExpression().Left
			if leftNull {
				operand = node.AsBinaryExpression().Right
			}
			test := ir.Expression(ir.IsNull{Value: value, AlwaysFalse: value.Type() != ir.Union && !l.includesNull(l.checker.GetTypeAtLocation(operand))})
			if operator == ast.KindExclamationEqualsEqualsToken {
				test = ir.Unary{Operator: ir.Not, Operand: test}
			}
			return test, nil
		}
		// x === undefined tests for a missing reference, whatever x's type.
		_, leftUndefined := left.(ir.Undefined)
		_, rightUndefined := right.(ir.Undefined)
		if leftUndefined != rightUndefined {
			value := left
			if leftUndefined {
				value = right
			}
			if pair := ir.Maybe(value.Type()); pair.IsMaybe() {
				// A number or a boolean the checker narrowed to present: still evaluated, and never
				// undefined.
				value = fit(value, pair)
			}
			if !value.Type().IsReference() && !value.Type().IsMaybe() {
				return nil, l.notYet(node, "comparing a "+typeName(value.Type())+" with undefined")
			}
			test := ir.Expression(ir.IsUndefined{Value: value})
			operand := node.AsBinaryExpression().Left
			if leftUndefined {
				operand = node.AsBinaryExpression().Right
			}
			if value.Type() != ir.Union && l.includesNull(l.checker.GetTypeAtLocation(operand)) {
				test = ir.IsNull{Value: value, AlwaysFalse: true}
			}
			if operator == ast.KindExclamationEqualsEqualsToken {
				test = ir.Unary{Operator: ir.Not, Operand: test}
			}
			return test, nil
		}
	}
	if (operator == ast.KindEqualsEqualsEqualsToken || operator == ast.KindExclamationEqualsEqualsToken) && left.Type() != right.Type() {
		// A pair against what it holds, or against another pair: each made a pair, and compared as one.
		if pair := left.Type(); pair.IsMaybe() && right.Type() == pair.Present() {
			right = fit(right, pair)
		} else if pair := right.Type(); pair.IsMaybe() && left.Type() == pair.Present() {
			left = fit(left, pair)
		} else if left.Type() == ir.Union || right.Type() == ir.Union {
			// A union against anything: both as unions, compared by member and value.
			left, right = fit(left, ir.Union), fit(right, ir.Union)
		}
	}
	if (operator == ast.KindEqualsEqualsEqualsToken || operator == ast.KindExclamationEqualsEqualsToken) && left.Type() == right.Type() {
		lowered := ir.Equal
		if operator == ast.KindExclamationEqualsEqualsToken {
			lowered = ir.NotEqual
		}
		return ir.Binary{Operator: lowered, Left: left, Right: right}, nil
	}
	if value, known := l.censusBooleanLogical(node, operator, left, right); known {
		return value, nil
	}
	if operator == ast.KindAmpersandAmpersandToken || operator == ast.KindBarBarToken {
		if !both(ir.Boolean) {
			of, err := l.typeOf(node)
			if err != nil {
				return nil, err
			}
			return ir.Logical{Left: left, Right: fit(right, of), Of: of, KeepTruthy: operator == ast.KindBarBarToken}, nil
		}
		lowered := ir.And
		if operator == ast.KindBarBarToken {
			lowered = ir.Or
		}
		return ir.Binary{Operator: lowered, Left: left, Right: right}, nil
	}

	return nil, l.notYet(node, describe(node)+" with a "+typeName(left.Type())+" and a "+typeName(right.Type()))
}

// spelled is a string as + and a template write it: one that may be missing (a null reference) is
// written "undefined", as JavaScript writes it.
func (l *lowering) spelled(node *ast.Node, value ir.Expression) ir.Expression {
	if value.Type() != ir.String || !(l.includesUndefined(l.checker.GetTypeAtLocation(node)) || l.narrowedAway(ast.SkipParentheses(node))) {
		return value
	}
	return ir.Coalesce{Value: value, Fallback: ir.StringConstant{Index: l.constant("undefined")}, Of: ir.String}
}

// template lowers a template literal to a Concat, writing each value as String() would.
func (l *lowering) template(node *ast.Node) (ir.Expression, error) {
	template := node.AsTemplateExpression()
	parts := []ir.Expression{}
	if head := template.Head.Text(); head != "" {
		parts = append(parts, ir.StringConstant{Index: l.constant(head)})
	}
	for _, span := range template.TemplateSpans.Nodes {
		value, err := l.expression(span.AsTemplateSpan().Expression)
		if err != nil {
			return nil, err
		}
		switch value.Type() {
		case ir.Number:
			value = ir.NumberToString{Value: value}
		case ir.Boolean:
			value = ir.BooleanToString{Value: value}
		case ir.MaybeNumber, ir.MaybeBoolean:
			value = ir.MaybeToString{Value: value}
		case ir.Union:
			if !l.writable(l.arrayPredicateObservedType(span.AsTemplateSpan().Expression)) {
				return nil, l.notYet(span, "a template interpolating a union with an object, an array, a map or a function in it")
			}
			value = ir.UnionToString{Value: value}
		case ir.String:
			value = l.spelled(span.AsTemplateSpan().Expression, value)
		default:
			// JavaScript writes an object as "[object Object]", an array as its join, and a function as
			// its source; 0.1 has no use for any of it.
			return nil, l.notYet(span, "a template interpolating an object, an array, a map, a function or undefined")
		}
		parts = append(parts, value)
		if literal := span.AsTemplateSpan().Literal.Text(); literal != "" {
			parts = append(parts, ir.StringConstant{Index: l.constant(literal)})
		}
	}
	return ir.Concat{Parts: parts}, nil
}

func (l *lowering) conditional(node *ast.Node) (ir.Expression, error) {
	if branch := l.literalCallableBranch(node); branch != nil {
		return l.expression(branch)
	}
	conditional := node.AsConditionalExpression()
	condition, err := l.condition(conditional.Condition)
	if err != nil {
		return nil, err
	}
	if l.isNever(conditional.WhenTrue) || l.isNever(conditional.WhenFalse) {
		return l.conditionalNever(node, condition)
	}
	whenTrue, err := l.expression(conditional.WhenTrue)
	if err != nil {
		return nil, err
	}
	whenNot, err := l.expression(conditional.WhenFalse)
	if err != nil {
		return nil, err
	}
	if whenTrue.Type() != whenNot.Type() && l.acceptsUndefined(node) {
		// A stale narrowing in either branch may still hold undefined. Keep that representation
		// when the whole conditional is observed or written into a slot that accepts it.
		if pair := whenTrue.Type(); pair.IsMaybe() && whenNot.Type() == pair.Present() {
			whenNot = fit(whenNot, pair)
		} else if pair := whenNot.Type(); pair.IsMaybe() && whenTrue.Type() == pair.Present() {
			whenTrue = fit(whenTrue, pair)
		}
	}
	if whenTrue.Type() != whenNot.Type() {
		// flag ? 1 : undefined is number | undefined, and flag ? 1 : 'one' a union: each branch made
		// one.
		if of, err := l.typeOf(node); err == nil && (of.IsMaybe() || of == ir.Union || of.IsReference()) {
			whenTrue, whenNot = fit(whenTrue, of), fit(whenNot, of)
		}
	}
	if whenTrue.Type() != whenNot.Type() {
		// flag ? text : undefined is a reference that may be missing, held as text is, with undefined
		// the null one: the checker's type for the whole says which.
		_, trueUndefined := whenTrue.(ir.Undefined)
		_, notUndefined := whenNot.(ir.Undefined)
		present := whenTrue
		if trueUndefined {
			present = whenNot
		}
		if of, err := l.typeOf(node); err == nil && trueUndefined != notUndefined && present.Type().IsReference() && of == present.Type() {
			return ir.Conditional{Condition: condition, WhenTrue: whenTrue, WhenNot: whenNot, Of: of}, nil
		}
		return nil, l.notYet(node, "a conditional whose branches have different types")
	}
	return ir.Conditional{Condition: condition, WhenTrue: whenTrue, WhenNot: whenNot}, nil
}

func typeName(valueType ir.Type) string {
	if valueType.IsTypedArray() {
		return typedArrayName(valueType)
	}
	switch valueType {
	case ir.Number:
		return "number"
	case ir.Boolean:
		return "boolean"
	case ir.String:
		return "string"
	case ir.MaybeNumber:
		return "number | undefined"
	case ir.MaybeBoolean:
		return "boolean | undefined"
	case ir.Union:
		return "union of differently held members"
	}
	return "value"
}

// writable reports whether every member of a union is one a template writes: a number, a boolean, a
// string or undefined.
func (l *lowering) writable(proven *checker.Type) bool {
	// Judge the members this instantiation stores, rather than the generic binder.
	proven = l.concrete(proven)
	members := []*checker.Type{proven}
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		members = proven.Types()
	}
	for _, member := range members {
		if member.Flags()&checker.TypeFlagsUndefined != 0 {
			continue
		}
		memberType, isKnown := l.representation(member)
		if !isKnown || (memberType != ir.Number && memberType != ir.Boolean && memberType != ir.String) {
			return false
		}
	}
	return true
}

// slotless reports whether a value of the type can't yet be held in one word: a field, an element, a
// map's value, a cell, or a function value's argument or result. number | undefined is packed into
// one (a reserved NaN is undefined); boolean | undefined has a tagged byte for object fields
// (censusFieldSlotless), but remains unsupported in the other slot contexts, and a
// Union has to be boxed on its way in, which stage 0 does only where a variable, a parameter or a
// result takes one.
func slotless(valueType ir.Type) bool {
	return valueType == ir.MaybeBoolean || valueType == ir.Union
}

// call lowers a call to one of the module's functions, or to a function value.
func (l *lowering) call(node *ast.Node) (ir.Expression, error) {
	call := node.AsCallExpression()
	callee := ast.SkipParentheses(call.Expression)
	if direct := l.nestedSibling(callee); direct >= 0 {
		arguments := []ir.Expression{}
		for _, argument := range call.Arguments.Nodes {
			value, err := l.expression(argument)
			if err != nil {
				return nil, err
			}
			position := len(arguments)
			if position < len(l.result.Functions[direct].Parameters) {
				value = fit(value, l.result.Locals[l.result.Functions[direct].Parameters[position]].Type)
			}
			arguments = append(arguments, value)
		}
		carrier := ir.Expression(ir.ClosureSelf{})
		if l.function.NestedParent != l.result.Functions[direct].NestedParent {
			// Anonymous captures have their own layout. Materialize a temporary carrier
			// for the target layout; do not capture a sibling's canonical function value.
			carrier = ir.MakeClosure{Function: direct}
		}
		return ir.CallClosure{Closure: carrier, Direct: direct + 1, Arguments: arguments, Returns: l.result.Functions[direct].Returns}, nil
	}
	qualified := l.namespaceMember(callee)
	if declaration, isGeneric := l.generics[l.symbol(callee)]; (ast.IsIdentifier(callee) || qualified) && isGeneric {
		instance, err := l.instantiateFunction(node, declaration)
		if err != nil {
			return nil, err
		}
		if l.result.Functions[instance].Closure {
			arguments := []ir.Expression{}
			for position, argument := range call.Arguments.Nodes {
				value, err := l.expression(argument)
				if err != nil {
					return nil, err
				}
				if position < len(l.result.Functions[instance].Parameters) {
					value = fit(value, l.result.Locals[l.result.Functions[instance].Parameters[position]].Type)
				}
				arguments = append(arguments, value)
			}
			value := ir.CallClosure{Closure: ir.MakeClosure{Function: instance}, Arguments: arguments, Returns: l.result.Functions[instance].Returns}
			return l.namespaceReadyCall(callee, value), nil
		}
		value, err := l.callFunction(call, instance)
		if err == nil {
			value = l.namespaceReadyCall(callee, value)
		}
		return value, err
	}
	function, isFunction := l.functions[l.symbol(callee)]
	if (!ast.IsIdentifier(callee) && !qualified) || !isFunction {
		if calleeType, _ := l.representation(l.checker.GetTypeAtLocation(callee)); calleeType == ir.Closure {
			return l.callClosure(node)
		}
		return nil, l.notYet(node, "a call to "+describe(callee))
	}
	value, err := l.callFunction(call, function)
	if err == nil {
		value = l.namespaceReadyCall(callee, value)
	}
	return value, err
}

// callFunction lowers a call's arguments, in order, and the call to function.
func (l *lowering) callFunction(call *ast.CallExpression, function int) (ir.Expression, error) {
	arguments, spread, err := l.callArguments(call.Arguments.Nodes)
	if err != nil {
		return nil, err
	}
	l.fitCallArguments(function, arguments, spread)
	return l.censusOverloadResult(call, ir.Call{Function: function, Arguments: arguments, Spread: spread, Returns: l.result.Functions[function].Returns})
}

// coalesce lowers value ?? fallback, and value ?? panic('why'), evaluating the right side only when
// the left is missing.
func (l *lowering) coalesce(node *ast.Node) (ir.Expression, error) {
	binary := node.AsBinaryExpression()
	value, err := l.expression(binary.Left)
	if err != nil {
		return nil, err
	}
	// What ?? makes is the checker's: the left side's present members and the right side's, which
	// may be held differently (text ?? count is string | number, a Union).
	of, err := l.typeOf(node)
	if err != nil {
		return nil, err
	}
	if present := value.Type(); !present.IsMaybe() && !present.IsReference() {
		// A value that can't be missing: ?? never runs its right side.
		return fit(value, of), nil
	}
	right := ast.SkipParentheses(binary.Right)
	if right.Kind == ast.KindCallExpression && l.isPreludeFunction(right.AsCallExpression().Expression, "panic") && len(right.AsCallExpression().Arguments.Nodes) == 1 {
		message, err := l.expression(right.AsCallExpression().Arguments.Nodes[0])
		if err != nil {
			return nil, err
		}
		return ir.Coalesce{Value: value, Panic: message, Of: of}, nil
	}
	if l.isNever(binary.Right) {
		fallback, err := l.neverValue(binary.Right, of)
		if err != nil {
			return nil, err
		}
		return ir.Coalesce{Value: value, Fallback: fallback, Of: of}, nil
	}
	fallback, err := l.expression(binary.Right)
	if err != nil {
		return nil, err
	}
	fallback = fit(fallback, of)
	if _, isUndefined := fallback.(ir.Undefined); fallback.Type() != of && !(isUndefined && of.IsReference()) {
		return nil, l.notYet(node, "?? whose sides have different types")
	}
	return ir.Coalesce{Value: value, Fallback: fallback, Of: of}, nil
}

// closure lowers an arrow function to a function of its own and the closure that captures it.
func (l *lowering) closure(node *ast.Node) (ir.Expression, error) {
	index := len(l.result.Functions)
	l.result.Functions = append(l.result.Functions, ir.Function{Name: "closure", Closure: true})
	l.closureRecords = append(l.closureRecords, closureRecord{proven: l.concrete(l.checker.GetTypeAtLocation(node)), function: index, node: node})
	if l.instance != nil {
		l.instance.templates = append(l.instance.templates, template{closure: index, proven: l.checker.GetTypeAtLocation(node), isClosure: true})
	}
	l.closures = append(l.closures, index)
	err := l.lowerFunction(index, node, -1)
	l.closures = l.closures[:len(l.closures)-1]
	if err != nil {
		return nil, err
	}
	return ir.MakeClosure{Function: index}, nil
}

// functionValue makes one stable adapter per named function. It binds optional
// and rest parameters and forwards the original count, even though its ordinary
// parameters have been padded or collected before reaching the target.
func (l *lowering) functionValue(node *ast.Node, target int) (ir.Expression, error) {
	symbol := l.symbol(node)
	if node.Kind == ast.KindShorthandPropertyAssignment {
		symbol = l.checker.GetShorthandAssignmentValueSymbol(node)
		if symbol != nil && symbol.Flags&ast.SymbolFlagsAlias != 0 {
			symbol = l.checker.GetAliasedSymbol(symbol)
		}
		symbol = l.checker.GetExportSymbolOfSymbol(symbol)
	}
	if symbol != nil {
		for _, declaration := range symbol.Declarations {
			if declaration.Kind == ast.KindFunctionDeclaration && declaration.Body() == nil && l.censusImplementation(declaration) != nil {
				return nil, l.notYet(node, "an overloaded function as a value")
			}
		}
	}
	if held, isMade := l.forwarders[target]; isMade {
		return ir.Read{Local: held, Of: ir.Closure}, nil
	}
	for _, parameter := range symbol.Declarations[0].Parameters() {
		if parameter.Name().Text() == "this" {
			return nil, l.notYet(parameter, "a function with a this parameter used as a value; pass the receiver explicitly or use an arrow")
		}
	}
	callee := l.result.Functions[target]
	if censusCallableSlotless(callee.Returns) {
		return nil, l.notYet(node, "a function value returning "+typeName(callee.Returns))
	}
	index := len(l.result.Functions)
	forwarder := ir.Function{Name: callee.Name + "_value", Closure: true, Returns: callee.Returns, RestElement: callee.RestElement, ForwardsArguments: target + 1}
	arguments := []ir.Expression{}
	for _, parameter := range callee.Parameters {
		declared := l.result.Locals[parameter]
		if censusCallableSlotless(declared.Type) {
			return nil, l.notYet(node, "a function value taking "+typeName(declared.Type))
		}
		local := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: declared.Name, Type: declared.Type, Function: index})
		forwarder.Parameters = append(forwarder.Parameters, local)
		arguments = append(arguments, ir.Read{Local: local, Of: declared.Type})
	}
	call := ir.Call{Function: target, Arguments: arguments, Returns: callee.Returns, ForwardCount: true, RestPacked: true}
	if callee.Returns == 0 {
		forwarder.Body = []ir.Statement{ir.Evaluate{Value: call}}
	} else {
		forwarder.Body = []ir.Statement{ir.Return{Value: call}}
	}
	l.result.Functions = append(l.result.Functions, forwarder)
	l.closureRecords = append(l.closureRecords, closureRecord{proven: l.concrete(l.checker.GetTypeAtLocation(node)), function: index, node: node})
	// One function value for the function, made before anything runs and held by a global of its
	// own, so reading the function twice gives the same value, === as JavaScript's.
	held := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: callee.Name + "_value", Type: ir.Closure, Global: true, Function: -1})
	l.forwarderValues = append(l.forwarderValues, ir.Declare{Local: held, Value: ir.MakeClosure{Function: index}})
	if l.forwarders == nil {
		l.forwarders = map[int]int{}
	}
	l.forwarders[target] = held
	return ir.Read{Local: held, Of: ir.Closure}, nil
}

// optionalCall refuses a call in an optional chain, text?.toUpperCase() or run?.(): the receiver has
// to be evaluated once and tested before the call, which stage 0 doesn't lower yet for the library's
// methods or a function value called directly. Lowered as a plain call, it ran the method on
// undefined. The one form lowered is object?.method(...) on a method the program declares (a
// class's, an interface's, or a function value in a field): the call goes through the object's
// methods, which stops at undefined as JavaScript's chain does (ir.Property's Method).
func (l *lowering) optionalCall(call *ast.Node) error {
	if call.Flags&ast.NodeFlagsOptionalChain == 0 || l.isOptionalJoin(call) {
		return nil
	}
	callee := ast.SkipParentheses(call.AsCallExpression().Expression)
	if callee.Kind == ast.KindPropertyAccessExpression && callee.AsPropertyAccessExpression().QuestionDotToken != nil && call.AsCallExpression().QuestionDotToken == nil {
		if method := l.checker.GetSymbolAtLocation(callee); method != nil && len(method.Declarations) > 0 && !load.IsLibrary(ast.GetSourceFileOfNode(method.Declarations[0])) {
			return nil
		}
	}
	return l.notYet(call, "a call through ?. (an optional call)")
}

// callClosure lowers a call through a function value.
func (l *lowering) callClosure(node *ast.Node) (ir.Expression, error) {
	signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(node.AsCallExpression().Expression), checker.SignatureKindCall)
	if len(signatures) == 1 && l.censusNeverRestSignature(signatures[0]) {
		// never[] admits a zero-argument call in TypeScript. The erased slot does
		// not retain a source signature to prove its required arguments or ABI.
		return nil, l.notYet(node, "a call through an erased never-rest callable marker")
	}
	closure, err := l.expression(node.AsCallExpression().Expression)
	if err != nil {
		return nil, err
	}
	if property, isProperty := closure.(ir.Property); isProperty {
		// object.name(...) through an interface: the object may be a class's, whose methods aren't
		// fields (ir.Property's Method).
		property.Method = true
		closure = property
	}
	arguments, spread, err := l.callArguments(node.AsCallExpression().Arguments.Nodes)
	if err != nil {
		return nil, err
	}
	var returns ir.Type
	if result := l.concrete(l.checker.GetTypeAtLocation(node)); result.Flags()&(checker.TypeFlagsVoid|checker.TypeFlagsNever) == 0 {
		var isKnown bool
		if returns, isKnown = l.representation(result); !isKnown {
			return nil, l.notYet(node, "a call returning "+l.checker.TypeToString(result))
		}
	}
	// Each argument is made what the function value takes: a number or undefined where it takes
	// number | undefined is packed as one.
	if signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(node.AsCallExpression().Expression), checker.SignatureKindCall); len(signatures) == 1 {
		parameters := signatures[0].Parameters()
		position := 0
		expanded := false
		for index := range arguments {
			if len(spread) > index && spread[index] {
				expanded = true
				continue
			}
			if len(parameters) == 0 {
				break
			}
			parameter := parameters[min(position, len(parameters)-1)]
			rest := len(parameter.Declarations) > 0 && parameter.Declarations[0].Kind == ast.KindParameter && parameter.Declarations[0].AsParameterDeclaration().DotDotDotToken != nil
			proven := l.checker.GetTypeOfSymbol(parameter)
			if rest {
				elements := l.checker.GetTypeArguments(proven)
				if len(elements) == 1 {
					proven = elements[0]
				}
			} else if expanded || position >= len(parameters) {
				position++
				continue
			}
			if takes, known := l.representation(proven); known {
				// The checker describes a defaulted parameter by its present type,
				// but its incoming slot must preserve undefined until the body runs.
				if !rest && len(parameter.Declarations) > 0 && parameter.Declarations[0].Kind == ast.KindParameter && parameter.Declarations[0].AsParameterDeclaration().Initializer != nil {
					takes = ir.Maybe(takes)
				}
				arguments[index] = fit(arguments[index], takes)
			}
			position++
		}
	}
	for _, argument := range arguments {
		if censusCallableSlotless(argument.Type()) {
			return nil, l.notYet(node, "passing "+typeName(argument.Type())+" to a function value")
		}
	}
	if censusCallableSlotless(returns) {
		return nil, l.notYet(node, "a function value returning "+typeName(returns))
	}
	return ir.CallClosure{Closure: closure, Arguments: arguments, Spread: spread, FunctionType: int(l.concrete(l.checker.GetTypeAtLocation(node.AsCallExpression().Expression)).Id()), Returns: returns}, nil
}

// Optional booleans have a three-state byte in the function-call ABI.
// General union arguments still need a representation adapter.
func argumentSlotless(valueType ir.Type) bool { return valueType == ir.Union }

internal/lower/lower.go:
// Package lower turns a checked program into Adamic's IR.
//
// Stage 0 lowers a little and refuses the rest. Every construct it can't lower yet is an error
// naming the construct and where it is, never a skip: a compiler that drops a statement it doesn't
// understand produces a program that looks right and isn't, which is the one thing Adamic must
// never do.
package lower

import (
	"context"
	"fmt"
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
	"path/filepath"
)

// Lower lowers a checked program from one entry, in ESM evaluation order.
func Lower(ctx context.Context, program *load.Program) (*ir.Program, error) {
	files := program.Files()
	if len(files) != 1 {
		return nil, fmt.Errorf("lower: stage 0 compiles a program from one entry file, got %d", len(files))
	}
	entry := files[0]
	// Stage 0 checks single-threaded, so one checker answers for every file.
	typeChecker, release := program.Checker(ctx, entry)
	defer release()

	lowering := &lowering{program: program, checker: typeChecker, result: &ir.Program{}, this: -1, functionIndex: -1}
	// The base name only, so the same program emits the same C on every machine.
	lowering.result.Source = filepath.Base(program.FileName(entry))
	modules, err := lowering.moduleOrder(entry)
	if err != nil {
		return nil, err
	}
	lowering.noteInheritance(modules)
	if err := lowering.enumInitialization(modules); err != nil {
		return nil, err
	}
	lowering.noteAccessorNames(modules)
	lowering.noteOmittedOptionals(modules)
	if err := lowering.namespaceInitialization(modules); err != nil {
		return nil, err
	}
	for _, module := range modules {
		if err := lowering.refuse(module); err != nil {
			return nil, err
		}
	}
	// Link every declaration before lowering any function body, including across back edges.
	var declarations []*ast.Node
	for _, module := range modules {
		declarations = append(declarations, module.Statements.Nodes...)
	}
	if err := lowering.declareModule(declarations); err != nil {
		return nil, err
	}
	for _, module := range modules {
		body, err := lowering.statements(module.Statements.Nodes)
		if err != nil {
			return nil, err
		}
		lowering.result.Main = append(lowering.result.Main, body...)
	}
	if lowering.unlowerable != nil {
		return nil, lowering.unlowerable
	}
	lowering.result.Main = append(lowering.forwarderValues, lowering.result.Main...)
	lowering.finishClassCalls()
	if err := lowering.finishAccessors(); err != nil {
		return nil, err
	}
	if err := lowering.exceptions(); err != nil {
		return nil, err
	}
	if err := lowering.checkAccessorSpreads(); err != nil {
		return nil, err
	}
	if err := lowering.findCycles(modules); err != nil {
		return nil, err
	}
	readiness(lowering.result)
	borrow(lowering.result)
	counters(lowering.result)
	return lowering.result, nil
}

type lowering struct {
	// V2 retains exact logical producer types for union member certification.
	untaggedCallableTargets map[ir.ViewContractID]*checker.Type

	program *load.Program
	checker *checker.Checker
	result  *ir.Program

	// cyclicModules keeps unresolved reads checked throughout a cyclic graph.
	cyclicModules     bool
	provenModuleReads map[*ast.Node]bool
	cycleReadFindings []Finding

	// strings indexes result.Strings, so a constant used twice is stored once.
	strings map[string]int

	// locals maps each variable's symbol to its index in result.Locals.
	locals map[*ast.Symbol]int

	// functions maps each function declaration's symbol to its index in result.Functions.
	functions map[*ast.Symbol]int

	// function is the function being lowered, or nil for the module's top level.
	function *ir.Function

	// this is the local this is in a method or constructor, or -1.
	this int

	// functionIndex is the function being lowered, -1 for the module's top level, and closures the
	// closures being lowered, outermost first, each inside the one before.
	functionIndex int
	closures      []int

	// classes maps each module class's symbol to its declaration, and instances each instantiation
	// already lowered (class.go).
	// omittedOptionals is every optional property some object literal typed by its context leaves out:
	// that object has no slot for it (class.go's absentOptionalWrite).
	omittedOptionals map[*ast.Symbol]bool
	classes          map[*ast.Symbol]*ast.Node
	statics          map[*ast.Symbol]*instance
	staticGlobals    map[*ast.Symbol]int
	instances        map[string]*instance
	derivedAncestors map[*ast.Symbol]bool

	// privateOwners numbers each class that declares a private name, in the order first met, to
	// qualify its private members' names (privateName).
	privateOwners map[*ast.Node]int

	// instance is the class instantiation being lowered, if any.
	instance *instance

	// substitution is what each type parameter stands for in the instantiation being lowered.
	substitution map[*checker.Type]ir.Type

	// unlowerable is the first construct found not lowerable somewhere that can't return an error.
	unlowerable error

	// alwaysUndefined are parameters that only ever receive undefined, whatever the checker calls
	// their type: the first of an Array.from callback's (from.go). Each is a reference that's always
	// missing.
	alwaysUndefined map[*ast.Symbol]bool

	// signed are the functions whose signatures are written and whose bodies aren't lowered yet, by
	// index, each with what its body still needs (signature).
	signed map[int]signed

	// forwarders are the globals holding the function values made for module functions read as values,
	// by the function each forwards to, and forwarderValues the declarations that make them, which run
	// before anything else (functionValue).
	forwarders      map[int]int
	forwarderValues []ir.Statement

	// unsetUntil is where, in the constructor being lowered, its last assignment of a field without an
	// initializer ends: before it, this is only for reading and writing fields (useOfThis).
	unsetUntil int

	// generics maps each generic module function's symbol to its declaration, and genericInstances
	// each instantiation already lowered to its function (generic.go). genericDepth counts the
	// instantiations being lowered inside one another.
	generics              map[*ast.Symbol]*ast.Node
	genericInstances      map[string]int
	classGenericInstances map[string]map[string]int
	genericDepth          int

	// caught are the variables a catch binds, each always an Error; tries are the try statements
	// lowered (exceptions.go).
	caught map[*ast.Symbol]bool
	tries  []tryRecord

	// initializing is the variables whose initializers are being lowered, by where each is declared.
	initializing map[int]*ast.Node

	// For the cycle finder (cycles.go): the checker's type of each local, and where it's declared;
	// every function value made, with its type; and the class type being instantiated, for this.
	localTypes     map[int]*checker.Type
	localAlso      map[int][]*checker.Type
	localNodes     map[int]*ast.Node
	closureRecords []closureRecord
	classType      *checker.Type
	classNode      *ast.Node

	// typeMapper is what the type parameters of the instantiation being lowered, and of those it's
	// inside, stand for; instantiated is every class type an instantiation was made for (instantiate.go).
	typeMapper   *typeMapper
	instantiated []*checker.Type

	// writeSites is every write into a slot lowering made, by its IR node's Site less one (fresh.go).
	writeSites       []writeSite
	accessorCaptures []accessorCapture
	accessorNames    map[string]bool
}
